function App() {
  const [lang, setLang] = useState<Language>(Language.ID);
  const [darkMode, setDarkMode] = useState(true);
  const [currentPage, setPage] = useState('home');
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Initial intro animation
    const timer = setTimeout(() => setIsLoading(false), 2500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (darkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [darkMode]);

  const changePage = (page: string) => {
    if (page === currentPage) return;
    setIsLoading(true);
    setTimeout(() => {
      setPage(page);
      setIsLoading(false);
    }, 1200);
  };

  const renderContent = () => {
    switch (currentPage) {
      case 'home': return <HomeScreen setPage={changePage} lang={lang} />;
      case 'products': return <ProductsScreen lang={lang} />;
      case 'claim': return <ClaimScreen lang={lang} />;
      case 'about': return <AboutScreen lang={lang} />;
      case 'console': return <ConsoleScreen lang={lang} />;
      default: return <HomeScreen setPage={changePage} lang={lang} />;
    }
  };

  return (
    <div className="h-screen w-screen bg-white dark:bg-[#050505] text-gray-900 dark:text-white overflow-hidden flex flex-col font-sans transition-colors duration-500">

      {isLoading && <WalkingLoader />}

      <AppHeader lang={lang} setLang={setLang} darkMode={darkMode} setDarkMode={setDarkMode} />

      <main className="flex-1 mt-16 mb-20 overflow-y-auto no-scrollbar">
        {renderContent()}
      </main>

      <BottomNav active={currentPage} setPage={changePage} lang={lang} />
    </div>
  );
}

export default App;

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer utilities {
  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }
  .no-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }
}

@layer components {
  /* Walking Path Animation */
  .path-line {
    stroke-dasharray: 150;
    stroke-dashoffset: 150;
    animation: draw-path 3s ease-in-out infinite alternate;
  }

  .path-walker {
    offset-path: path("M50 95C50 95 35 75 35 55C35 35 50 35 55 25");
    animation: move-dot 3s ease-in-out infinite alternate;
  }

  @keyframes draw-path {
    0% { stroke-dashoffset: 150; }
    100% { stroke-dashoffset: 0; }
  }

  @keyframes move-dot {
    0% { offset-distance: 0%; opacity: 0; }
    10% { opacity: 1; }
    90% { opacity: 1; }
    100% { offset-distance: 100%; opacity: 0; }
  }

  /* Animations */
  .animate-fade-in {
    animation: fadeIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  }

  .animate-pop-in {
    animation: popIn 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
  }

  @keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
  }

  @keyframes popIn {
    0% { transform: scale(0.9); opacity: 0; }
    100% { transform: scale(1); opacity: 1; }
  }
}

/* Base resets */
body {
