}

import { GoogleGenAI } from "@google/genai";

const apiKey = process.env.API_KEY;
const ai = apiKey ? new GoogleGenAI({ apiKey }) : null;

export interface AnalysisResult {
  success: boolean;
  data?: {
    isCar: boolean;
    isClear: boolean;
    isWhole: boolean;
    hasDamage: boolean;
    damageDescription: string;
    score: number;
    reasons?: string[];
    [key: string]: any;
  };
  error?: string;
}

export interface ImpactedPart {
  part: string;
  action: 'Repair' | 'Replace';
  estimatedIdr: number;
}

export interface ClaimAnalysisResult {
  success: boolean;
  data?: {
    validImage: boolean;
    severity: 'Low' | 'Medium' | 'High' | 'Total Loss';
    estimatedCost: string;
    totalEstimate: number;
    impactedParts: ImpactedPart[];
    recommendation: string;
    aiInsight: string;
  };
  error?: string;
}

export const analyzeVehiclePhoto = async (base64Images: string[], labels: string[]): Promise<AnalysisResult> => {
  if (!ai) {
    console.warn("Gemini API Key missing. Returning mock data for demo purposes.");
    await new Promise(resolve => setTimeout(resolve, 3500)); 

    const isComplete = base64Images.length >= 8;
    const randomScore = Math.floor(Math.random() * 20) + 80;

    return {
      success: true,
      data: {
        isCar: true,
        isClear: true,
        isWhole: isComplete,
        hasDamage: false,
        damageDescription: isComplete 
          ? "Vehicle confirmed: Brand, Color, and Plate match input. No visible dents on 4 sides. Documents are legible." 
          : "Incomplete submission. Please provide all 8 required photos.",
        score: isComplete ? randomScore : 65,
        reasons: isComplete ? [] : ["Missing required angles"]
      }
    };
  }

  const modelId = 'gemini-2.5-flash'; 

  const prompt = `
    You are SurePath Neural AI, an expert insurance underwriter. Analyze these ${base64Images.length} images for car insurance verification.
    The images correspond to: ${labels.join(', ')}.

    Strictly validate:
    1. Completeness: Are all 8 required angles/docs present? (KTP, STNK Front/Back, Car Front/Back/Left/Right, Dashboard)
    2. Condition: Are there dents, scratches, or pre-existing damage?
    3. Legibility: Are documents readable?
    4. Consistency: Does the car in all photos look like the same vehicle?

    Return JSON:
    {
      "isCar": boolean,
      "isClear": boolean,
      "hasDamage": boolean,
      "damageDescription": string (detailed),
      "score": number (0-100. <80 implies rejection),
      "reasons": string[] (list of specific reasons if score < 100, e.g. "Dent on left door", "Blurry STNK")
    }
  `;

  try {
    const parts: any[] = [{ text: prompt }];

    base64Images.forEach(img => {
      const cleanBase64 = img.includes(',') ? img.split(',')[1] : img;
      parts.push({ inlineData: { mimeType: "image/jpeg", data: cleanBase64 } });
    });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: [{ role: "user", parts: parts }],
      config: { responseMimeType: "application/json" }
    });

    const text = response.text;
    if (!text) return { success: false, error: "No response from AI." };

    try {
      const data = JSON.parse(text);
      return { success: true, data };
    } catch (parseError) {
      return { success: false, error: "Invalid JSON format from AI." };
    }

  } catch (error: any) {
    console.error("Analysis Failed:", error);
    return { success: false, error: "Verification service unavailable." };
  }
};

export const analyzeClaimPhoto = async (base64Image: string): Promise<ClaimAnalysisResult> => {
  if (!ai) {
    console.warn("Gemini API Key missing. Returning mock claim data.");
    await new Promise(resolve => setTimeout(resolve, 3000));
    return {
      success: true,
      data: {
        validImage: true,
        severity: 'Medium',
        estimatedCost: 'Rp 4.750.000',
        totalEstimate: 4750000,
        impactedParts: [
          { part: 'Front Bumper', action: 'Replace', estimatedIdr: 3500000 },
          { part: 'Left Fog Lamp', action: 'Replace', estimatedIdr: 750000 },
          { part: 'Left Fender', action: 'Repair', estimatedIdr: 500000 }
        ],
        aiInsight: 'Primary impact detected on the lower front-left quadrant. Structural frame appears intact, but secondary vibrations may have loosened fog lamp housing.',
        recommendation: 'Proceed to Authorized Workshop (Platinum Partner) for genuine part replacement and paint matching.'
      }
    };
  }

  const modelId = 'gemini-2.5-flash';
  const prompt = `
    You are SurePath Neural AI, a specialized automotive damage computer vision system.
    Analyze this vehicle damage photo for an insurance claim.

    Tasks:
    1. Determine if the image contains valid car damage.
    2. Estimate severity (Low/Medium/High/Total Loss).
    3. Identify specific impacted parts.
    4. For each part, decide if it needs "Repair" or "Replace" based on damage depth and safety.
    5. Estimate cost in IDR (Indonesian Rupiah) based on standard Indonesian market rates.
    6. Provide a technical AI insight about the impact.

    Return JSON:
    {
      "validImage": boolean,
      "severity": "Low" | "Medium" | "High" | "Total Loss",
      "estimatedCost": string (formatted currency),
      "totalEstimate": number (raw IDR total),
      "impactedParts": [
        { "part": "string", "action": "Repair" | "Replace", "estimatedIdr": number }
      ],
      "aiInsight": "Technical description of findings",
      "recommendation": "Step-by-step repair advice"
    }
  `;

  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: [{ role: "user", parts: [{ text: prompt }, { inlineData: { mimeType: "image/jpeg", data: cleanBase64 } }] }],
      config: { responseMimeType: "application/json" }
    });

    const text = response.text;
    if (!text) return { success: false, error: "No response from AI." };

    const data = JSON.parse(text);
    return { success: true, data };
  } catch (error: any) {
    console.error("Claim Analysis Failed:", error);
    return { success: false, error: "AI Service Unavailable" };
  }
};

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer utilities {
  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }
  .no-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }

  .animation-delay-2000 {
    animation-delay: 2s;
  }
}

@layer components {
  /* Walking Path Animation */
  .path-line {
    stroke-dasharray: 150;
    stroke-dashoffset: 150;
    animation: draw-path 3s ease-in-out infinite alternate;
  }

  .path-walker {
    offset-path: path("M50 95C50 95 35 75 35 55C35 35 50 35 55 25");
    animation: move-dot 3s ease-in-out infinite alternate;
  }

  @keyframes draw-path {
    0% { stroke-dashoffset: 150; }
    100% { stroke-dashoffset: 0; }
  }

  @keyframes move-dot {
    0% { offset-distance: 0%; opacity: 0; }
    10% { opacity: 1; }
    90% { opacity: 1; }
    100% { offset-distance: 100%; opacity: 0; }
  }

  /* Animations */
  .animate-fade-in {
    animation: fadeIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  }

  .animate-pop-in {
    animation: popIn 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
  }

  @keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
  }

  @keyframes popIn {
    0% { transform: scale(0.9); opacity: 0; }
    100% { transform: scale(1); opacity: 1; }
  }

  /* Blob Animation for Auth Screen */
  @keyframes blob {
    0% { transform: translate(0px, 0px) scale(1); }
    33% { transform: translate(30px, -50px) scale(1.1); }
    66% { transform: translate(-20px, 20px) scale(0.9); }
    100% { transform: translate(0px, 0px) scale(1); }
  }

  .animate-blob {
    animation: blob 7s infinite alternate;
  }
}

