    brand: '', modelCode: '', year: 2024, price: 0, plateRegion: '2',
    plateDetails: { code: 'B', number: '', suffix: '' },
    usage: 'PERSONAL', condition: 'NEW', vin: '', engineNo: '', accessories: '',
    insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: { flood: false, earthquake: false, srcc: false, terrorism: false, authorizedWorkshop: false, tpl: 0, paDriver: 0, paPassenger: 0, passengers: 1 },
    photos: { ktp: null, stnkFront: null, stnkBack: null, carFront: null, carBack: null, carLeft: null, carRight: null, dashboard: null },
    selectedProvider: null
  });
  const [user, setUser] = useState<UserState>({ name: '', ktp: '', domicile: '', email: '', phone: '', isMember: false });
  const [loadingAI, setLoadingAI] = useState(false);

  const calculatePremium = () => {
    if (!vehicle.price) return 0;
    const rate = getOJKRate(vehicle.price, vehicle.plateRegion, vehicle.insuranceType);
    let total = (vehicle.price * 1000000) * (rate / 100);

    // Extensions
    const sumInsured = vehicle.price * 1000000;
    if (vehicle.expansions.flood) total += sumInsured * (EXPANSION_RATES.FLOOD / 100);
    if (vehicle.expansions.earthquake) total += sumInsured * (EXPANSION_RATES.EARTHQUAKE / 100);
    if (vehicle.expansions.srcc) {
      const srccRate = vehicle.insuranceType === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
      total += sumInsured * (srccRate / 100);
    }
    if (vehicle.expansions.authorizedWorkshop && vehicle.insuranceType === InsuranceType.COMPREHENSIVE) {
      total += sumInsured * (AUTHORIZED_WORKSHOP_RATE / 100);
    }
    if (vehicle.expansions.tpl > 0) total += (vehicle.expansions.tpl * 1000000) * 0.01; // Simplistic flat 1% of TPL sum for demo

    return Math.floor(total);
  };

