    recommendation: string;
    aiInsight: string;
  };
  error?: string;
}

/**
 * Analyzes vehicle photos for underwriting verification using Gemini 3.
 */
export const analyzeVehiclePhoto = async (base64Images: string[], labels: string[]): Promise<AnalysisResult> => {
  // Use gemini-3-pro-preview for complex reasoning and multi-modal tasks
  const modelId = 'gemini-3-pro-preview'; 

  const prompt = `
    You are SurePath Neural AI, an expert insurance underwriter. Analyze these ${base64Images.length} images for car insurance verification.
    The images correspond to: ${labels.join(', ')}.

    Strictly validate:
    1. Completeness: Are all 8 required angles/docs present? (KTP, STNK Front/Back, Car Front/Back/Left/Right, Dashboard)
    2. Condition: Are there dents, scratches, or pre-existing damage?
    3. Legibility: Are documents readable?
    4. Consistency: Does the car in all photos look like the same vehicle?

    Return JSON:
    {
      "isCar": boolean,
      "isClear": boolean,
      "hasDamage": boolean,
      "damageDescription": string (detailed),
      "score": number (0-100. <80 implies rejection),
      "reasons": string[] (list of specific reasons if score < 100, e.g. "Dent on left door", "Blurry STNK")
    }
  `;

  try {
    const parts: any[] = [{ text: prompt }];

    base64Images.forEach(img => {
      const cleanBase64 = img.includes(',') ? img.split(',')[1] : img;
      parts.push({ inlineData: { mimeType: "image/jpeg", data: cleanBase64 } });
    });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: parts },
      config: { responseMimeType: "application/json" }
    });

    // Access the .text property directly from GenerateContentResponse
    const text = response.text;
    if (!text) return { success: false, error: "No response from AI." };

    try {
      const data = JSON.parse(text);
      return { success: true, data };
    } catch (parseError) {
      return { success: false, error: "Invalid JSON format from AI." };
    }

  } catch (error: any) {
    console.error("Analysis Failed:", error);
    return { success: false, error: "Verification service unavailable." };
  }
};

/**
 * Analyzes vehicle damage photos to estimate claim severity and costs.
 */
export const analyzeClaimPhoto = async (base64Image: string): Promise<ClaimAnalysisResult> => {
  // Use gemini-3-pro-preview for advanced reasoning on damage assessment
  const modelId = 'gemini-3-pro-preview';
  const prompt = `
    You are SurePath Neural AI, a specialized automotive damage computer vision system.
    Analyze this vehicle damage photo for an insurance claim.

    Tasks:
    1. Determine if the image contains valid car damage.
    2. Estimate severity (Low/Medium/High/Total Loss).
    3. Identify specific impacted parts.
    4. For each part, decide if it needs "Repair" or "Replace" based on damage depth and safety.
    5. Estimate cost in IDR (Indonesian Rupiah) based on standard Indonesian market rates.
    6. Provide a technical AI insight about the impact.

    Return JSON:
    {
      "validImage": boolean,
      "severity": "Low" | "Medium" | "High" | "Total Loss",
      "estimatedCost": string (formatted currency),
      "totalEstimate": number (raw IDR total),
      "impactedParts": [
        { "part": "string", "action": "Repair" | "Replace", "estimatedIdr": number }
      ],
      "aiInsight": "Technical description of findings",
      "recommendation": "Step-by-step repair advice"
    }
  `;

  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: [{ text: prompt }, { inlineData: { mimeType: "image/jpeg", data: cleanBase64 } }] },
      config: { responseMimeType: "application/json" }
    });

    // Extract text directly from the response object property
    const text = response.text;
    if (!text) return { success: false, error: "No response from AI." };

    const data = JSON.parse(text);
