const CarInsuranceWizard = ({ lang, setPage }: any) => {
  const [step, setStep] = useState(1);
  const [loadingAI, setLoadingAI] = useState(false);
  const [aiScores, setAiScores] = useState<Record<string, {score: number, remarks: string}>>({});
  const [ocrLoading, setOcrLoading] = useState<string | null>(null);

  const [vehicle, setVehicle] = useState<VehicleState>({
    brand: '', modelCode: '', year: 2024, price: 0, plateRegion: '2',
    plateDetails: { code: 'B', number: '', suffix: '' },
    usage: 'PERSONAL', condition: 'NEW', vin: '', engineNo: '', accessories: '',
    insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: { flood: false, earthquake: false, srcc: false, terrorism: false, authorizedWorkshop: false, tpl: 0, paDriver: 0, paPassenger: 0, passengers: 1 },
    photos: { ktp: null, stnkFront: null, stnkBack: null, carFront: null, carBack: null, carLeft: null, carRight: null, dashboard: null },
    selectedProvider: null
  });
  const [user, setUser] = useState<UserState>({ name: '', ktp: '', domicile: '', email: '', phone: '', isMember: false });

  const calculatePremium = () => {
    if (!vehicle.price) return 0;
    const rate = getOJKRate(vehicle.price, vehicle.plateRegion, vehicle.insuranceType);
    let total = (vehicle.price * 1000000) * (rate / 100);

    const sumInsured = vehicle.price * 1000000;
    if (vehicle.expansions.flood) total += sumInsured * (EXPANSION_RATES.FLOOD / 100);
    if (vehicle.expansions.earthquake) total += sumInsured * (EXPANSION_RATES.EARTHQUAKE / 100);
    if (vehicle.expansions.srcc) {
      const srccRate = vehicle.insuranceType === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
      total += sumInsured * (srccRate / 100);
    }
    if (vehicle.expansions.authorizedWorkshop && vehicle.insuranceType === InsuranceType.COMPREHENSIVE) {
      total += sumInsured * (AUTHORIZED_WORKSHOP_RATE / 100);
    }
    if (vehicle.expansions.tpl > 0) total += (vehicle.expansions.tpl * 1000000) * 0.01; 

    return Math.floor(total);
  };

  const handleNext = () => setStep(step + 1);
  const handleBack = () => setStep(step - 1);

  const handleFileUpload = async (key: keyof VehicleState['photos'], file: File) => {
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setVehicle(v => ({ ...v, photos: { ...v.photos, [key]: base64 } }));

      // Auto OCR for documents
      if (key === 'ktp' || key === 'stnkFront') {
        setOcrLoading(key);
        const res = await performOCR(base64, key === 'ktp' ? 'KTP' : 'STNK');
        if (res.success && res.data) {
          if (res.data.type === 'KTP') {
            setUser(u => ({ ...u, name: res.data!.extractedData.Nama || u.name, ktp: res.data!.extractedData.NIK || u.ktp }));
          } else if (res.data.type === 'STNK') {
              const brand = res.data.extractedData.Brand || '';
              const year = parseInt(res.data.extractedData.Year) || 2024;
              const plate = res.data.extractedData.Plate || '';
              // Match with DB if possible
              const matchedCar = CAR_DATABASE.find(c => c.brand.toLowerCase() === brand.toLowerCase());
              setVehicle(v => ({ 
                  ...v, 
                  brand: matchedCar?.brand || brand,
                  year: year,
                  plateDetails: { 
                    ...v.plateDetails, 
                    number: plate.replace(/[^0-9]/g, '').slice(0, 4),
                    code: plate.split(' ')[0] || 'B'
                  }
              }));
          }
        }
        setOcrLoading(null);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleVerifyAll = async () => {
    setLoadingAI(true);
    const photosToVerify = [
      { label: 'Front', data: vehicle.photos.carFront! },
      { label: 'Back', data: vehicle.photos.carBack! },
      { label: 'Left', data: vehicle.photos.carLeft! },
      { label: 'Right', data: vehicle.photos.carRight! }
    ];

    const res = await analyzeVehiclePhotos(photosToVerify, {
      brand: vehicle.brand,
      model: vehicle.modelCode,
      year: vehicle.year,
      plate: `${vehicle.plateDetails.code} ${vehicle.plateDetails.number} ${vehicle.plateDetails.suffix}`
    });

    if (res.success && res.data) {
      const scoresMap: any = {};
      res.data.photoScores.forEach(ps => {
        scoresMap[ps.label] = { score: ps.score, remarks: ps.remarks };
      });
      setAiScores(scoresMap);
      if (res.data.overallScore >= 80) {
        setTimeout(handleNext, 1500);
      }
    }
    setLoadingAI(false);
  };

  const renderVehicleStep = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="space-y-2">
        <h3 className="text-xl font-black">{lang === Language.ID ? 'Detail Kendaraan' : 'Vehicle Details'}</h3>
        <p className="text-xs text-gray-500">{lang === Language.ID ? 'Pilih mobil Anda untuk mendapatkan estimasi harga pasar otomatis.' : 'Select your car to auto-fetch market price.'}</p>
      </div>

      <div className="grid gap-4">
        <div>
          <label className="text-[0.65rem] font-black text-gray-400 uppercase tracking-widest">{lang === Language.ID ? 'Merek' : 'Brand'}</label>
          <select 
            className="w-full p-4 mt-1 bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-white/10 rounded-2xl outline-none focus:border-primary-500 transition-colors"
            value={vehicle.brand}
            onChange={(e) => setVehicle({...vehicle, brand: e.target.value, modelCode: ''})}
          >
            <option value="">{lang === Language.ID ? 'Pilih Merek' : 'Select Brand'}</option>
            {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).map(b => <option key={b} value={b}>{b}</option>)}
          </select>
        </div>

        {vehicle.brand && (
          <div>
            <label className="text-[0.65rem] font-black text-gray-400 uppercase tracking-widest">{lang === Language.ID ? 'Model' : 'Model'}</label>
            <select 
              className="w-full p-4 mt-1 bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-white/10 rounded-2xl outline-none focus:border-primary-500 transition-colors"
              value={vehicle.modelCode}
              onChange={(e) => {
                const model = CAR_DATABASE.find(c => c.code === e.target.value);
                setVehicle({...vehicle, modelCode: e.target.value, price: model?.yearPrices[vehicle.year] || 0});
              }}
            >
              <option value="">{lang === Language.ID ? 'Pilih Model' : 'Select Model'}</option>
              {CAR_DATABASE.filter(c => c.brand === vehicle.brand).map(m => <option key={m.code} value={m.code}>{m.modelName}</option>)}
            </select>
          </div>
        )}

        {vehicle.modelCode && (
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[0.65rem] font-black text-gray-400 uppercase tracking-widest">{lang === Language.ID ? 'Tahun' : 'Year'}</label>
              <select 
                className="w-full p-4 mt-1 bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-white/10 rounded-2xl outline-none focus:border-primary-500 transition-colors"
                value={vehicle.year}
                onChange={(e) => {
                  const y = Number(e.target.value);
                  const model = CAR_DATABASE.find(c => c.code === vehicle.modelCode);
                  setVehicle({...vehicle, year: y, price: model?.yearPrices[y] || 0});
                }}
              >
                {Object.keys(CAR_DATABASE.find(c => c.code === vehicle.modelCode)?.yearPrices || {}).map(y => <option key={y} value={y}>{y}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[0.65rem] font-black text-gray-400 uppercase tracking-widest">{lang === Language.ID ? 'Harga Pasar (Juta)' : 'Market Price (Mio)'}</label>
              <div className="p-4 mt-1 bg-primary-500/10 border border-primary-500/20 rounded-2xl font-black text-primary-600">
                Rp {vehicle.price} Juta
              </div>
            </div>
          </div>
        )}
      </div>

      <button disabled={!vehicle.price} onClick={handleNext} className="w-full py-4 bg-primary-500 text-white rounded-2xl font-black uppercase tracking-widest shadow-lg shadow-primary-500/20 active:scale-95 transition-all">
        {lang === Language.ID ? 'Pilih Perlindungan' : 'Choose Coverage'}
      </button>
    </div>
  );

  const renderCoverageStep = () => (
    <div className="space-y-6 animate-fade-in">
       <div className="space-y-2">
          <h3 className="text-xl font-black">{lang === Language.ID ? 'Pilih Paket' : 'Select Package'}</h3>
          <p className="text-xs text-gray-500">{lang === Language.ID ? 'Tentukan tipe pertanggungan dan tambahan manfaat.' : 'Determine coverage type and add-ons.'}</p>
       </div>

       <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={() => setVehicle({...vehicle, insuranceType: InsuranceType.COMPREHENSIVE})}
            className={`p-5 rounded-3xl border-2 transition-all flex flex-col items-center gap-3 ${vehicle.insuranceType === InsuranceType.COMPREHENSIVE ? 'border-primary-500 bg-primary-500/5' : 'border-gray-100 dark:border-white/5 opacity-60'}`}
          >
            <ShieldCheck size={32} className={vehicle.insuranceType === InsuranceType.COMPREHENSIVE ? 'text-primary-500' : 'text-gray-400'} />
            <span className="text-xs font-black uppercase">Comprehensive</span>
          </button>
          <button 
            onClick={() => setVehicle({...vehicle, insuranceType: InsuranceType.TLO})}
            className={`p-5 rounded-3xl border-2 transition-all flex flex-col items-center gap-3 ${vehicle.insuranceType === InsuranceType.TLO ? 'border-primary-500 bg-primary-500/5' : 'border-gray-100 dark:border-white/5 opacity-60'}`}
          >
            <ShieldAlert size={32} className={vehicle.insuranceType === InsuranceType.TLO ? 'text-primary-500' : 'text-gray-400'} />
            <span className="text-xs font-black uppercase">Total Loss Only</span>
          </button>
       </div>

       <div className="space-y-3">
          <p className="text-[0.65rem] font-black text-gray-400 uppercase tracking-widest mb-2">{lang === Language.ID ? 'Manfaat Tambahan' : 'Add-on Expansions'}</p>
          {[
            { key: 'flood', label: lang === Language.ID ? 'Banjir & Topan' : 'Flood & Storm' },
            { key: 'earthquake', label: lang === Language.ID ? 'Gempa & Tsunami' : 'Earthquake' },
            { key: 'srcc', label: lang === Language.ID ? 'Huru-hara (SRCC)' : 'Riot (SRCC)' },
            { key: 'authorizedWorkshop', label: lang === Language.ID ? 'Bengkel Resmi (Auth)' : 'Authorized Workshop' },
          ].map(item => (
            <div key={item.key} onClick={() => setVehicle({...vehicle, expansions: {...vehicle.expansions, [item.key]: !(vehicle.expansions as any)[item.key]}})} className={`flex items-center justify-between p-4 rounded-2xl border transition-all cursor-pointer ${ (vehicle.expansions as any)[item.key] ? 'border-primary-500 bg-primary-500/5' : 'border-gray-100 dark:border-white/5' }`}>
               <span className="text-sm font-bold">{item.label}</span>
               {(vehicle.expansions as any)[item.key] ? <CheckCircle2 size={18} className="text-primary-500" /> : <div className="w-[18px] h-[18px] rounded-full border-2 border-gray-200" />}
