       <h2 className="text-3xl font-black">{lang === Language.ID ? 'Pendaftaran Berhasil!' : 'Registration Complete!'}</h2>
       <p className="text-sm text-gray-500 dark:text-gray-400 max-w-xs mx-auto">{lang === Language.ID ? 'Polis asuransi Anda telah diterbitkan secara digital dan dikirim ke email Anda.' : 'Your insurance policy has been digitally issued and sent to your email.'}</p>

