             </div>
             <div className="flex-1 text-right">
                <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest">Premium Paid</p>
                <p className="text-sm font-bold text-emerald-500">Rp {(calculatePremium() + STAMP_DUTY + 50000).toLocaleString()}</p>
             </div>
          </div>
       </div>

       <div className="space-y-3 pt-6">
          <button className="w-full py-4 bg-gray-900 dark:bg-white dark:text-black text-white rounded-2xl font-black uppercase tracking-widest text-xs shadow-lg">{lang === Language.ID ? 'Unduh E-Polis' : 'Download E-Policy'}</button>
          <button onClick={() => setPage('home')} className="w-full py-4 bg-gray-100 dark:bg-white/5 rounded-2xl font-black uppercase tracking-widest text-xs border border-gray-200 dark:border-white/10">{lang === Language.ID ? 'Ke Beranda' : 'Go to Dashboard'}</button>
       </div>
    </div>
  );

  return (
    <div className="max-w-md mx-auto p-6 min-h-[80vh] flex flex-col justify-center">
       {step < 6 && (
         <div className="flex items-center gap-4 mb-8">
            <button onClick={handleBack} disabled={step === 1} className="p-2 bg-gray-100 dark:bg-white/5 rounded-xl disabled:opacity-30"><ChevronLeft size={20} /></button>
            <div className="flex-1 bg-gray-100 dark:bg-white/5 h-2 rounded-full overflow-hidden">
               <div className="bg-primary-500 h-full transition-all duration-700" style={{width: `${(step/5)*100}%`}}></div>
            </div>
            <span className="text-[0.65rem] font-black text-gray-400">{step}/5</span>
         </div>
       )}

       {step === 1 && renderVehicleStep()}
       {step === 2 && renderCoverageStep()}
       {step === 3 && renderProviderStep()}
       {step === 4 && renderPersonalStep()}
       {step === 5 && renderAICheckStep()}
       {step === 6 && renderSuccessStep()}
    </div>
  );
};

