         <div className="flex items-center gap-4 mb-8">
            <button onClick={handleBack} disabled={step === 1} className="p-2 bg-gray-100 dark:bg-white/5 rounded-xl disabled:opacity-30"><ChevronLeft size={20} /></button>
            <div className="flex-1 bg-gray-100 dark:bg-white/5 h-2 rounded-full overflow-hidden">
               <div className="bg-primary-500 h-full transition-all duration-700" style={{width: `${(step/5)*100}%`}}></div>
            </div>
            <span className="text-[0.65rem] font-black text-gray-400">{step}/5</span>
         </div>
       )}

       {step === 1 && renderVehicleStep()}
       {step === 2 && renderCoverageStep()}
       {step === 3 && renderProviderStep()}
       {step === 4 && renderPersonalStep()}
       {step === 5 && renderAICheckStep()}
       {step === 6 && renderSuccessStep()}
    </div>
  );
};

