    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setVehicle(v => ({ ...v, photos: { ...v.photos, [key]: base64 } }));

      // Auto OCR for documents
      if (key === 'ktp' || key === 'stnkFront') {
        setOcrLoading(key);
        const res = await performOCR(base64, key === 'ktp' ? 'KTP' : 'STNK');
        if (res.success && res.data) {
          if (res.data.type === 'KTP') {
            setUser(u => ({ ...u, name: res.data!.extractedData.Nama || u.name, ktp: res.data!.extractedData.NIK || u.ktp }));
          } else if (res.data.type === 'STNK') {
              const brand = res.data.extractedData.Brand || '';
              const year = parseInt(res.data.extractedData.Year) || 2024;
              const plate = res.data.extractedData.Plate || '';
              const matchedCar = CAR_DATABASE.find(c => c.brand.toLowerCase() === brand.toLowerCase());
              setVehicle(v => ({ 
                  ...v, 
                  brand: matchedCar?.brand || brand,
                  year: year,
                  plateDetails: { 
                    ...v.plateDetails, 
                    number: plate.replace(/[^0-9]/g, '').slice(0, 4),
                    code: plate.split(' ')[0] || 'B'
                  }
              }));
          }
        }
        setOcrLoading(null);
      }
    };
    reader.readAsDataURL(file);
  };

