const ClaimScreen = ({ lang, setPage }: any) => {
  const [analyzing, setAnalyzing] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [result, setResult] = useState<any>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setImagePreview(base64);
        handleAnalysis(base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalysis = async (base64: string) => {
    setAnalyzing(true);
    const res = await analyzeClaimPhoto(base64);
    if (res.success) {
      setResult(res.data);
    }
    setAnalyzing(false);
  };

  const handleFileClaim = async () => {
    setSubmitting(true);
    await new Promise(r => setTimeout(r, 2500));
    setSubmitting(false);
    setIsSubmitted(true);
  };

  const triggerUpload = () => {
    fileInputRef.current?.click();
  };

  if (isSubmitted) {
    return (
      <div className="p-5 min-h-full flex flex-col animate-fade-in bg-white dark:bg-[#050505]">
        <div className="flex-1 flex flex-col items-center justify-center text-center space-y-6 pt-10">
          <div className="relative">
             <div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center shadow-2xl shadow-emerald-500/30 animate-pop-in relative z-10">
               <CheckCircle2 size={56} className="text-white" />
             </div>
             <div className="absolute inset-0 bg-emerald-500/20 rounded-full animate-ping scale-150 opacity-20"></div>
          </div>

          <div className="space-y-2">
            <h2 className="text-3xl font-black">{lang === Language.ID ? 'Klaim Berhasil!' : 'Claim Registered!'}</h2>
