    handleNext();
  };

  const renderVehicleStep = () => {
    const brands = Array.from(new Set(CAR_DATABASE.map(c => c.brand))).filter(b => b.toLowerCase().includes(brandSearch.toLowerCase()));
    const models = CAR_DATABASE.filter(c => c.brand === vehicle.brand);
    const selectedModel = CAR_DATABASE.find(c => c.code === vehicle.modelCode);
    const availableYears = selectedModel ? Object.keys(selectedModel.yearPrices).map(Number).sort((a,b) => b-a) : [];

    return (
      <div className="space-y-8 animate-fade-in pb-12">
        <div className="space-y-2">
          <h3 className="text-2xl font-black">{lang === Language.ID ? 'Informasi Kendaraan' : 'Vehicle Information'}</h3>
          <p className="text-xs text-gray-500">{lang === Language.ID ? 'Isi detail kendaraan Anda dengan tepat.' : 'Enter your vehicle details accurately.'}</p>
        </div>
        <div className="space-y-4">
          <div className="relative group">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input type="text" placeholder={lang === Language.ID ? 'Cari merek...' : 'Search brands...'} className="w-full bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-white/10 rounded-2xl py-4 pl-12 pr-4 outline-none focus:border-primary-500 transition-all" value={brandSearch} onChange={(e) => setBrandSearch(e.target.value)} />
          </div>
          <div className="flex gap-3 overflow-x-auto no-scrollbar pb-2">
            {brands.map(b => (
              <button key={b} onClick={() => setVehicle({...vehicle, brand: b, modelCode: '', price: 0})} className={`shrink-0 px-6 py-4 rounded-2xl font-black text-sm border-2 transition-all ${vehicle.brand === b ? 'bg-primary-500 text-white border-primary-500 shadow-lg shadow-primary-500/20' : 'bg-white dark:bg-white/5 border-gray-100 dark:border-white/10 text-gray-500'}`}>{b}</button>
            ))}
