              {models.map(m => (
                <button key={m.code} onClick={() => { const latestYear = Object.keys(m.yearPrices).map(Number).sort((a,b) => b-a)[0]; setVehicle({...vehicle, modelCode: m.code, year: latestYear, price: m.yearPrices[latestYear]}); }} className={`flex items-center justify-between p-5 rounded-2xl border-2 transition-all ${vehicle.modelCode === m.code ? 'border-primary-500 bg-primary-500/5' : 'border-gray-100 dark:border-white/10 bg-white dark:bg-white/5'}`}>
