const ClaimScreen = ({ lang, setPage }: any) => {
  const [analyzing, setAnalyzing] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [result, setResult] = useState<any>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence: Load on mount
  useEffect(() => {
    const saved = localStorage.getItem('surepath_claim_draft');
    if (saved) {
      const parsed = JSON.parse(saved);
      setImagePreview(parsed.image);
      setResult(parsed.result);
    }
  }, []);

  // Persistence: Save on update
  useEffect(() => {
    if (imagePreview || result) {
      localStorage.setItem('surepath_claim_draft', JSON.stringify({ image: imagePreview, result }));
    }
  }, [imagePreview, result]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setImagePreview(base64);
        handleAnalysis(base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalysis = async (base64: string) => {
    setAnalyzing(true);
    const res = await analyzeClaimPhoto(base64);
    if (res.success) setResult(res.data);
    setAnalyzing(false);
  };

  const handleFileClaim = async () => {
    setAnalyzing(true);
    await new Promise(r => setTimeout(r, 1500));
    logTransaction({
      type: 'CLAIM_FILED',
      customer: 'Alex Jhonson',
      severity: result.severity,
      estCost: result.estimatedCost
    });
    localStorage.removeItem('surepath_claim_draft');
    setIsSubmitted(true);
    setAnalyzing(false);
  };

  if (isSubmitted) {
    return (
      <div className="p-5 flex flex-col items-center justify-center text-center space-y-6 pt-10 animate-fade-in">
        <div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center shadow-2xl animate-pop-in"><CheckCircle2 size={56} className="text-white" /></div>
        <h2 className="text-3xl font-black">Claim Registered!</h2>
        <p className="text-sm text-gray-500 max-w-xs">Our admin team has received your neural AI audit. You will be contacted shortly.</p>
        <button onClick={() => setPage('home')} className="w-full py-4 bg-primary-500 text-white rounded-2xl font-black uppercase text-xs">Return Dashboard</button>
      </div>
    );
  }

  return (
    <div className="p-5 min-h-full flex flex-col animate-fade-in pb-20">
      <div className="text-center mt-2 mb-6">
        <div className="inline-flex items-center gap-2 px-3 py-1 bg-primary-500/10 rounded-full mb-3">
          <Sparkles size={14} className="text-primary-500" />
          <span className="text-[0.65rem] font-black uppercase text-primary-600">SurePath Neural AI</span>
        </div>
        <h2 className="text-2xl font-black">Claim Analysis</h2>
      </div>

      {!imagePreview ? (
        <div className="flex-1 flex flex-col items-center justify-center">
          <button onClick={() => fileInputRef.current?.click()} className="w-56 h-56 rounded-[3rem] bg-gradient-to-br from-primary-400 to-emerald-700 flex flex-col items-center justify-center text-white shadow-2xl border-8 border-white/10 group">
            <Camera size={44} />
            <p className="text-xs font-black uppercase mt-3">Snap Damage</p>
            <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFileChange} />
          </button>
        </div>
      ) : (
        <div className="space-y-6 animate-pop-in">
           <img src={imagePreview} className="w-full rounded-3xl aspect-video object-cover" />
           {analyzing ? <Loader2 size={32} className="mx-auto text-primary-500 animate-spin" /> : (
             result && (
               <div className="bg-white dark:bg-white/5 rounded-3xl p-6 border border-gray-100 dark:border-white/10 shadow-xl space-y-4">
                  <div className="flex justify-between items-center">
                    <h3 className="text-xl font-black text-primary-500">{result.estimatedCost}</h3>
                    <span className="px-3 py-1 bg-yellow-500 text-black text-[0.6rem] font-black rounded-full uppercase">{result.severity}</span>
                  </div>
                  <p className="text-[0.7rem] text-gray-500 leading-relaxed italic">{result.aiInsight}</p>
                  <div className="flex gap-3">
                    <button onClick={() => {setImagePreview(null); setResult(null); localStorage.removeItem('surepath_claim_draft');}} className="flex-1 py-4 bg-gray-100 rounded-2xl font-black uppercase text-xs">Reset</button>
                    <button onClick={handleFileClaim} className="flex-[2] py-4 bg-primary-500 text-white rounded-2xl font-black uppercase text-xs">Submit Claim</button>
                  </div>
               </div>
             )
           )}
        </div>
      )}
    </div>
  );
};

