            </div>
            <span className="text-[0.65rem] font-black text-gray-400">{step}/6</span>
         </div>
       )}
       {step === 1 && renderVehicleStep()}
       {step === 2 && renderCoverageStep()}
       {/* Other steps abbreviated for conciseness as Step 1 & 2 & 5 were core requests */}
       {step === 3 && (
          <div className="space-y-6 animate-fade-in">
             <h3 className="text-2xl font-black">Select Provider</h3>
             <div className="space-y-4">
                {INSURANCE_PROVIDERS.map(p => (
                   <button key={p.id} onClick={() => { setVehicle({...vehicle, selectedProvider: p}); handleNext(); }} className="w-full p-6 rounded-3xl border-2 border-gray-100 dark:border-white/10 flex items-center justify-between hover:border-primary-500 transition-all">
                      <div className="flex items-center gap-4">
                         <div className="w-12 h-12 bg-white dark:bg-white/10 rounded-xl flex items-center justify-center text-primary-500"><p.logo size={24}/></div>
                         <p className="font-black text-sm">{p.name}</p>
                      </div>
                      <ChevronRight size={20} className="text-gray-400"/>
                   </button>
                ))}
             </div>
          </div>
       )}
       {step === 4 && (
          <div className="space-y-6 animate-fade-in">
            <h3 className="text-2xl font-black">Customer Profile</h3>
            <div className="space-y-4">
               <input type="text" placeholder="Full Name" className="w-full p-4 rounded-2xl bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-white/10 outline-none focus:border-primary-500 font-bold" value={user.name} onChange={(e) => setUser({...user, name: e.target.value})} />
               <input type="text" placeholder="NIK (ID Number)" className="w-full p-4 rounded-2xl bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-white/10 outline-none focus:border-primary-500 font-bold" value={user.ktp} onChange={(e) => setUser({...user, ktp: e.target.value})} />
               <button onClick={handleNext} className="w-full py-5 bg-primary-500 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl">Audit AI</button>
            </div>
          </div>
       )}
       {step === 5 && renderAICheckStep()}
       {step === 6 && (
          <div className="space-y-6 animate-fade-in">
             <h3 className="text-2xl font-black">Final Confirmation</h3>
             <div className="bg-gray-50 dark:bg-white/5 p-6 rounded-[2.5rem] border border-gray-100 dark:border-white/10 space-y-4">
                <div className="flex justify-between border-b dark:border-white/5 pb-2"><span className="text-xs text-gray-500">Customer</span><span className="text-xs font-bold">{user.name}</span></div>
                <div className="flex justify-between border-b dark:border-white/5 pb-2"><span className="text-xs text-gray-500">Premium</span><span className="text-xs font-black text-primary-500">Rp {pData.total.toLocaleString()}</span></div>
             </div>
             <button onClick={handleComplete} className="w-full py-5 bg-primary-500 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl">Complete Payment</button>
          </div>
       )}
       {step === 7 && renderSuccess()}
    </div>
  );
};

