const ClaimScreen = ({ lang, setPage }: any) => {
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<any>(() => {
    const saved = localStorage.getItem('surepath_claim_draft');
    return saved ? JSON.parse(saved).result : null;
  });
  const [imagePreview, setImagePreview] = useState<string | null>(() => {
    const saved = localStorage.getItem('surepath_claim_draft');
    return saved ? JSON.parse(saved).image : null;
  });

  useEffect(() => {
    if (imagePreview || result) {
      localStorage.setItem('surepath_claim_draft', JSON.stringify({ image: imagePreview, result }));
    }
  }, [imagePreview, result]);

  const handleFile = async (e: any) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setImagePreview(base64);
        setAnalyzing(true);
        const res = await analyzeClaimPhoto(base64);
        if (res.success) setResult(res.data);
        setAnalyzing(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const submitClaim = () => {
    logTransaction({
      type: 'CLAIM_FILED',
      customer: 'Alex Jhonson',
      severity: result.severity,
      estCost: result.estimatedCost,
      timestamp: new Date().toISOString()
    });
    localStorage.removeItem('surepath_claim_draft');
    setResult(null);
    setImagePreview(null);
    alert("Claim Submitted to Admin Console");
    setPage('home');
  };

  return (
    <div className="p-6 max-w-md mx-auto space-y-8 animate-fade-in pb-24">
      <div className="text-center space-y-2">
        <h2 className="text-3xl font-black">AI Claim Service</h2>
        <p className="text-xs text-gray-500">Your progress is automatically saved to local storage.</p>
      </div>

      {!imagePreview ? (
        <div className="flex flex-col items-center justify-center h-64 border-4 border-dashed border-gray-100 dark:border-white/5 rounded-[3rem] space-y-4">
          <Camera size={48} className="text-gray-300"/>
          <button className="relative bg-primary-500 text-white px-8 py-3 rounded-2xl font-black uppercase text-xs shadow-xl">
             Snap Car Damage
             <input type="file" className="absolute inset-0 opacity-0" onChange={handleFile} />
          </button>
        </div>
      ) : (
        <div className="space-y-6 animate-pop-in">
           <img src={imagePreview} className="w-full rounded-3xl aspect-video object-cover border border-gray-100 dark:border-white/10" />
           {analyzing ? (
             <div className="flex flex-col items-center gap-3 py-6"><Loader2 size={32} className="text-primary-500 animate-spin"/><p className="text-xs font-bold uppercase tracking-widest">Neural Analysis...</p></div>
           ) : (
             result && (
               <div className="bg-white dark:bg-white/5 p-6 rounded-[2.5rem] border border-gray-100 dark:border-white/10 shadow-2xl space-y-4">
                  <div className="flex justify-between items-center"><h4 className="text-xl font-black text-primary-500">{result.estimatedCost}</h4><span className="bg-yellow-500 text-black px-3 py-1 rounded-full text-[0.6rem] font-black uppercase">{result.severity}</span></div>
                  <p className="text-[0.7rem] text-gray-500 leading-relaxed italic">{result.aiInsight}</p>
                  <div className="flex gap-3">
                    <button onClick={() => { setImagePreview(null); setResult(null); localStorage.removeItem('surepath_claim_draft'); }} className="flex-1 py-4 border-2 rounded-2xl font-black uppercase text-xs">Reset</button>
                    <button onClick={submitClaim} className="flex-[2] py-4 bg-primary-500 text-white rounded-2xl font-black uppercase text-xs shadow-xl">Submit Claim</button>
                  </div>
               </div>
             )
           )}
        </div>
      )}
    </div>
  );
};

