import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface PhotoScore {
  label: string;
  score: number; 
  clarity: number;
  angle: number;
  lighting: number;
  status: 'valid' | 'invalid';
  remarks: string;
}

export interface AnalysisResult {
  success: boolean;
  data?: {
    overallScore: number;
    photoScores: PhotoScore[];
    dataMatch: {
      brandMatch: boolean;
      yearMatch: boolean;
      plateMatch: boolean;
    };
    insights: string;
  };
  error?: string;
}

export interface OCRResult {
  success: boolean;
  data?: {
    type: 'KTP' | 'STNK';
    extractedData: Record<string, string>;
    confidence: number;
  };
  error?: string;
}

export const performOCR = async (base64Image: string, docType: 'KTP' | 'STNK'): Promise<OCRResult> => {
  const modelId = 'gemini-3-pro-preview';
  const prompt = docType === 'KTP' 
    ? `Extract Indonesian KTP data: NIK, Nama. Return JSON: {"NIK": "...", "Nama": "..."}`
    : `Extract Indonesian STNK data: No. Polisi, Merk/Tipe, Tahun Pembuatan. Return JSON: {"Plate": "...", "Brand": "...", "Type": "...", "Year": "..."}`;

  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: [{ text: prompt }, { inlineData: { mimeType: "image/jpeg", data: cleanBase64 } }] },
      config: { responseMimeType: "application/json" }
    });

    const text = response.text;
    if (!text) return { success: false, error: "AI failed to read document." };
    return { success: true, data: { type: docType, extractedData: JSON.parse(text), confidence: 0.95 } };
  } catch (error) {
    return { success: false, error: "OCR Service Unavailable" };
  }
};

export const analyzeVehiclePhotos = async (
  photos: { label: string, data: string }[], 
  inputData: { brand: string, model: string, year: number, plate: string }
): Promise<AnalysisResult> => {
  const modelId = 'gemini-3-pro-preview';
  const prompt = `
    TASK: STRICT VEHICLE AUDIT FOR INSURANCE.
    Vehicle to Verify: ${inputData.brand} ${inputData.model} (${inputData.year}), Plate: ${inputData.plate}.

    AUDIT RULES (MANDATORY):
    1. Overall score MUST be below 80 if any damage is detected (dents, scratches, cracks).
    2. Overall score MUST be below 80 if lighting is dark or image is blurry.
    3. Mismatch in brand, model, or plate results in score < 40.
    4. Vehicle must look "Brand New" quality to pass with > 80.

    Return JSON only:
    {
      "overallScore": number (0-100),
      "photoScores": [
        { "label": "string", "score": number, "clarity": number, "angle": number, "lighting": number, "status": "valid"|"invalid", "remarks": "Detailed analysis of surface quality" }
      ],
      "dataMatch": { "brandMatch": boolean, "yearMatch": boolean, "plateMatch": boolean },
      "insights": "Description of why it passed or failed (e.g., 'Found scratch on left door')."
    }
  `;

  try {
    const parts: any[] = [{ text: prompt }];
    photos.forEach(p => {
      const cleanBase64 = p.data.includes(',') ? p.data.split(',')[1] : p.data;
      parts.push({ inlineData: { mimeType: "image/jpeg", data: cleanBase64 } });
    });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: parts },
      config: { responseMimeType: "application/json" }
    });

    const text = response.text;
    if (!text) return { success: false, error: "Analysis failed." };
    return { success: true, data: JSON.parse(text) };
  } catch (error) {
    return { success: false, error: "AI Analysis Service Unavailable" };
  }
};

export const analyzeClaimPhoto = async (base64Image: string) => {
  const modelId = 'gemini-3-pro-preview';
  const prompt = `Analyze vehicle damage for claim. Return JSON: {"severity": "Low"|"Medium"|"High"|"Total Loss", "estimatedCost": "...", "damagePoints": ["..."], "recommendation": "...", "aiInsight": "..."}`;
  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: [{ text: prompt }, { inlineData: { mimeType: "image/jpeg", data: cleanBase64 } }] },
      config: { responseMimeType: "application/json" }
    });
    return { success: true, data: JSON.parse(response.text || '{}') };
  } catch (error) {
    return { success: false };
  }
};

