               <input className="w-32 bg-white/10 text-white p-3 rounded-xl text-center text-xl font-black outline-none" placeholder="1234" value={vehicle.plateDetails.number} onChange={(e) => setVehicle({...vehicle, plateDetails: {...vehicle.plateDetails, number: e.target.value.replace(/\D/g,'')}})} maxLength={4} />
               <input className="w-20 bg-white/10 text-white p-3 rounded-xl text-center text-xl font-black outline-none" placeholder="ABC" value={vehicle.plateDetails.suffix} onChange={(e) => setVehicle({...vehicle, plateDetails: {...vehicle.plateDetails, suffix: e.target.value.toUpperCase()}})} maxLength={3} />
            </div>
            <button onClick={handleNext} className="w-full py-5 bg-primary-500 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl">Select Plan & Coverage</button>
          </div>
        )}
      </div>
    );
  };

  const renderCoverageStep = () => (
    <div className="space-y-8 animate-fade-in pb-12">
      <div className="space-y-2 text-center">
        <h3 className="text-2xl font-black">Plan Customization</h3>
        <p className="text-xs text-gray-500">Configure expansions and Third Party Liability (TPL) limits.</p>
      </div>

      <div className="grid grid-cols-2 gap-4">
