            ) : (
              <Camera size={48} className="text-gray-300 group-hover:text-primary-500 transition-colors" />
            )}
            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => e.target.files?.[0] && handleUpload(e.target.files[0])} />
          </div>
          <button onClick={startAnalysis} disabled={!photo || analyzing} className="w-full py-5 bg-primary-500 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl flex items-center justify-center gap-2 active:scale-95 transition-all">
