const CarInsuranceWizard = ({ setPage }: any) => {
  const [step, setStep] = useState(1);
  const [loadingAI, setLoadingAI] = useState(false);
  const [aiError, setAiError] = useState<string | null>(null);
  const [brandSearch, setBrandSearch] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<string | null>(null);
  const [uploadSuccess, setUploadSuccess] = useState(false);

  const [vehicle, setVehicle] = useState<VehicleState>(() => {
    const saved = localStorage.getItem('surepath_wizard_draft');
    return saved ? JSON.parse(saved).vehicle : {
      brand: '', modelCode: '', year: 2025, price: 0, plateRegion: '2',
      plateDetails: { code: 'B', number: '', suffix: '' },
      usage: 'PERSONAL', condition: 'NEW', vin: '', engineNo: '', accessories: '',
      insuranceType: InsuranceType.COMPREHENSIVE,
      expansions: { flood: false, earthquake: false, srcc: false, terrorism: false, authorizedWorkshop: false, tpl: 0, paDriver: 0, paPassenger: 0, passengers: 1 },
      photos: { ktp: null, stnkFront: null, stnkBack: null, carFront: null, carBack: null, carLeft: null, carRight: null, dashboard: null },
      selectedProvider: null
    };
  });

  const [user, setUser] = useState<UserState>(() => {
    const saved = localStorage.getItem('surepath_wizard_draft');
    return saved ? JSON.parse(saved).user : { name: '', ktp: '', domicile: '', email: '', phone: '', isMember: false };
  });

  useEffect(() => {
    localStorage.setItem('surepath_wizard_draft', JSON.stringify({ vehicle, user }));
  }, [vehicle, user]);

  const calculatePremiumDetails = () => {
    const sumInsured = vehicle.price * 1000000;
    const rate = getOJKRate(vehicle.price, vehicle.plateRegion, vehicle.insuranceType);
    const base = sumInsured * (rate / 100);

    const floodCost = vehicle.expansions.flood ? sumInsured * (EXPANSION_RATES.FLOOD / 100) : 0;
    const earthquakeCost = vehicle.expansions.earthquake ? sumInsured * (EXPANSION_RATES.EARTHQUAKE / 100) : 0;
    const srccCost = vehicle.expansions.srcc ? sumInsured * (vehicle.insuranceType === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO / 100) : 0;
    const authCost = (vehicle.expansions.authorizedWorkshop && vehicle.insuranceType === InsuranceType.COMPREHENSIVE) ? sumInsured * (AUTHORIZED_WORKSHOP_RATE / 100) : 0;
    const tplCost = vehicle.expansions.tpl > 0 ? (vehicle.expansions.tpl * 10000) : 0; 

    const total = base + floodCost + earthquakeCost + srccCost + authCost + tplCost;
    return { base, floodCost, earthquakeCost, srccCost, authCost, tplCost, total };
  };

  const pData = calculatePremiumDetails();

  const handleNext = () => setStep(step + 1);
  const handleBack = () => setStep(step - 1);

  const handleFileUpload = (key: keyof VehicleState['photos'], file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      setVehicle(v => ({ ...v, photos: { ...v.photos, [key]: reader.result as string } }));
    };
    reader.readAsDataURL(file);
  };

  const handleVerifyAI = async () => {
    setLoadingAI(true);
    setAiError(null);
    const photosToVerify = [
      { label: 'Front', data: vehicle.photos.carFront! },
      { label: 'Back', data: vehicle.photos.carBack! },
      { label: 'Left', data: vehicle.photos.carLeft! },
      { label: 'Right', data: vehicle.photos.carRight! }
    ];

    const res = await analyzeVehiclePhotos(photosToVerify, {
      brand: vehicle.brand,
      model: vehicle.modelCode,
      year: vehicle.year,
      plate: `${vehicle.plateDetails.code} ${vehicle.plateDetails.number} ${vehicle.plateDetails.suffix}`
    });

    if (res.success && res.data) {
      if (res.data.overallScore < 80) {
        setAiError(res.data.insights || "AI Audit failed quality threshold. Please retake photos in better lighting.");
        setLoadingAI(false);
      } else {
        setUploadSuccess(true);
        setTimeout(handleNext, 1500);
      }
    } else {
      setAiError("AI Engine Service Error. Try again.");
      setLoadingAI(false);
    }
  };

  const handlePayment = () => {
    const totalWithAdmin = pData.total + (vehicle.selectedProvider?.adminFee || 0) + STAMP_DUTY;
    logTransaction({
      type: 'CAR_INSURANCE',
      customer: user.name,
      vehicle: `${vehicle.brand} ${vehicle.modelCode} (${vehicle.year})`,
      premium: totalWithAdmin,
      provider: vehicle.selectedProvider?.name,
      method: paymentMethod
    });
    localStorage.removeItem('surepath_wizard_draft');
    handleNext();
  };

  const renderVehicleStep = () => {
    const brands = Array.from(new Set(CAR_DATABASE.map(c => c.brand))).filter(b => b.toLowerCase().includes(brandSearch.toLowerCase()));
    const models = CAR_DATABASE.filter(c => c.brand === vehicle.brand);

