    return saved ? JSON.parse(saved).user : { name: '', ktp: '', domicile: '', email: '', phone: '', isMember: false };
  });

  useEffect(() => {
    localStorage.setItem('surepath_wizard_draft', JSON.stringify({ vehicle, user }));
  }, [vehicle, user]);

  const calculatePremiumDetails = () => {
    if (!vehicle.price) return { base: 0, floodCost: 0, earthquakeCost: 0, srccCost: 0, authCost: 0, tplCost: 0, total: 0 };
    const sumInsured = vehicle.price * 1000000;
    const rate = getOJKRate(vehicle.price, vehicle.plateRegion, vehicle.insuranceType);
    const base = sumInsured * (rate / 100);

    const floodCost = vehicle.expansions.flood ? sumInsured * (EXPANSION_RATES.FLOOD / 100) : 0;
    const earthquakeCost = vehicle.expansions.earthquake ? sumInsured * (EXPANSION_RATES.EARTHQUAKE / 100) : 0;
    const srccCost = vehicle.expansions.srcc ? sumInsured * (vehicle.insuranceType === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO / 100) : 0;
    const authCost = (vehicle.expansions.authorizedWorkshop && vehicle.insuranceType === InsuranceType.COMPREHENSIVE) ? sumInsured * (AUTHORIZED_WORKSHOP_RATE / 100) : 0;
    const tplCost = vehicle.expansions.tpl > 0 ? (vehicle.expansions.tpl * 10000) : 0; 

    const total = base + floodCost + earthquakeCost + srccCost + authCost + tplCost;
    return { base, floodCost, earthquakeCost, srccCost, authCost, tplCost, total };
  };

  const pData = calculatePremiumDetails();

  const handleNext = () => setStep(prev => prev + 1);
  const handleBack = () => setStep(prev => prev - 1);

  const handleFileUpload = (key: keyof VehicleState['photos'], file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      setVehicle(v => ({ ...v, photos: { ...v.photos, [key]: reader.result as string } }));
    };
    reader.readAsDataURL(file);
  };

  const handleVerifyAI = async () => {
    setLoadingAI(true);
    setAiError(null);
    const requiredPhotos = [
      vehicle.photos.ktp, vehicle.photos.stnkFront, vehicle.photos.stnkBack,
      vehicle.photos.carFront, vehicle.photos.carBack, vehicle.photos.carLeft, vehicle.photos.carRight,
      vehicle.photos.dashboard
    ].filter(p => !!p);

    if (requiredPhotos.length < 8) {
      setAiError("Please upload all 8 required photos before auditing.");
      setLoadingAI(false);
      return;
    }

    const labels = ["KTP", "STNK Front", "STNK Back", "Front", "Back", "Left", "Right", "Dashboard"];
    const res = await analyzeVehiclePhoto(requiredPhotos as string[], labels);

    if (res.success && res.data) {
      if (res.data.score < 80) {
        setAiError(res.data.reasons?.join(". ") || res.data.damageDescription);
        setLoadingAI(false);
      } else {
        setUploadSuccess(true);
        setTimeout(handleNext, 1500);
      }
    } else {
      setAiError("AI Engine Service Error. Try again.");
      setLoadingAI(false);
    }
  };

  const handlePayment = () => {
    logTransaction({
      type: 'CAR_INSURANCE',
      customer: user.name,
      vehicle: `${vehicle.brand} ${vehicle.modelCode} (${vehicle.year})`,
      premium: pData.total + STAMP_DUTY + 50000,
      method: paymentMethod
    });
    localStorage.removeItem('surepath_wizard_draft');
    handleNext();
  };

  const renderVehicleStep = () => {
    const brands = Array.from(new Set(CAR_DATABASE.map(c => c.brand))).filter(b => b.toLowerCase().includes(brandSearch.toLowerCase()));
    const models = CAR_DATABASE.filter(c => c.brand === vehicle.brand);

    return (
      <div className="space-y-8 animate-fade-in pb-12 max-w-md mx-auto w-full">
        <div className="space-y-2">
          <h3 className="text-2xl font-black">Vehicle Identification</h3>
          <p className="text-xs text-gray-500">Pick your car brand and model for instant valuation.</p>
        </div>

        <div className="space-y-4">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input 
              type="text" placeholder="Search Brand..." 
              className="w-full bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-white/10 rounded-2xl py-4 pl-12 pr-4 outline-none focus:border-primary-500 transition-all text-sm" 
              value={brandSearch} onChange={(e) => setBrandSearch(e.target.value)} 
            />
          </div>
          <div className="grid grid-cols-3 gap-3">
            {brands.slice(0, 6).map(b => (
              <button 
                key={b} onClick={() => setVehicle({...vehicle, brand: b, modelCode: '', price: 0})}
                className={`p-4 rounded-2xl border-2 transition-all text-sm font-black ${vehicle.brand === b ? 'border-primary-500 bg-primary-500/5 text-primary-500 shadow-lg' : 'border-gray-100 dark:border-white/10 bg-white dark:bg-white/5'}`}
              >
                {b}
              </button>
            ))}
          </div>
        </div>

        {vehicle.brand && (
          <div className="space-y-4 animate-fade-in">
             <p className="text-[0.6rem] font-black uppercase text-gray-400 tracking-[0.2em]">Select Model</p>
             <div className="grid grid-cols-1 gap-2">
               {models.map(m => (
                 <button 
                   key={m.code} onClick={() => setVehicle({...vehicle, modelCode: m.modelName, price: Object.values(m.yearPrices)[0]})}
                   className={`w-full p-4 rounded-2xl border-2 transition-all flex items-center justify-between font-bold text-sm ${vehicle.modelCode === m.modelName ? 'border-primary-500 bg-primary-500/5 text-primary-500' : 'border-gray-100 dark:border-white/10 bg-white dark:bg-white/5'}`}
                 >
                   {m.modelName}
                   {vehicle.modelCode === m.modelName && <CheckCircle2 size={18} className="text-primary-500"/>}
                 </button>
               ))}
             </div>
          </div>
        )}

        {vehicle.modelCode && (
          <div className="space-y-4 animate-fade-in pt-4">
            <p className="text-[0.6rem] font-black uppercase text-gray-400 tracking-[0.2em]">License Plate</p>
            <div className="bg-black p-4 rounded-3xl flex items-center gap-3 justify-center border-4 border-gray-800">
               <input className="w-16 bg-white/10 text-white p-3 rounded-xl text-center text-xl font-black outline-none uppercase" placeholder="B" value={vehicle.plateDetails.code} onChange={(e) => { const reg = getRegionFromPlate(e.target.value); setVehicle({...vehicle, plateRegion: reg, plateDetails: {...vehicle.plateDetails, code: e.target.value.toUpperCase()}}); }} maxLength={2} />
               <input className="w-32 bg-white/10 text-white p-3 rounded-xl text-center text-xl font-black outline-none" placeholder="1234" value={vehicle.plateDetails.number} onChange={(e) => setVehicle({...vehicle, plateDetails: {...vehicle.plateDetails, number: e.target.value.replace(/\D/g,'')}})} maxLength={4} />
               <input className="w-20 bg-white/10 text-white p-3 rounded-xl text-center text-xl font-black outline-none uppercase" placeholder="ABC" value={vehicle.plateDetails.suffix} onChange={(e) => setVehicle({...vehicle, plateDetails: {...vehicle.plateDetails, suffix: e.target.value.toUpperCase()}})} maxLength={3} />
            </div>
            <button onClick={handleNext} className="w-full py-5 bg-primary-500 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl shadow-primary-500/20 active:scale-95 transition-all">Select Coverage</button>
          </div>
        )}
      </div>
    );
  };

  const renderCoverageStep = () => (
    <div className="space-y-8 animate-fade-in pb-12 max-w-md mx-auto w-full">
      <div className="space-y-2 text-center">
        <h3 className="text-2xl font-black">Plan Customization</h3>
        <p className="text-xs text-gray-500">Configure expansions and Third Party Liability (TPL) limits.</p>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <button onClick={() => setVehicle({...vehicle, insuranceType: InsuranceType.COMPREHENSIVE})} className={`p-6 rounded-3xl border-2 transition-all text-center ${vehicle.insuranceType === InsuranceType.COMPREHENSIVE ? 'border-primary-500 bg-primary-500/5' : 'border-gray-100 dark:border-white/10'}`}>
          <ShieldCheck size={32} className="mx-auto mb-2 text-primary-500"/>
          <p className="text-xs font-black uppercase">Comprehensive</p>
        </button>
        <button onClick={() => setVehicle({...vehicle, insuranceType: InsuranceType.TLO})} className={`p-6 rounded-3xl border-2 transition-all text-center ${vehicle.insuranceType === InsuranceType.TLO ? 'border-primary-500 bg-primary-500/5' : 'border-gray-100 dark:border-white/10'}`}>
          <ShieldAlert size={32} className="mx-auto mb-2 text-primary-500"/>
          <p className="text-xs font-black uppercase">Total Loss Only</p>
        </button>
      </div>

      <div className="space-y-4">
        <p className="text-[0.6rem] font-black uppercase text-gray-400 tracking-[0.2em]">Add-on Expansions</p>
        {[
          { id: 'flood', label: 'Flood & Storm', rate: '0.05%', icon: CloudRain, price: (vehicle.price * 1000000 * 0.0005) },
          { id: 'earthquake', label: 'Earthquake', rate: '0.10%', icon: Activity, price: (vehicle.price * 1000000 * 0.001) },
          { id: 'srcc', label: 'Riot (SRCC)', rate: '0.05%', icon: AlertTriangle, price: (vehicle.price * 1000000 * 0.0005) },
        ].map(opt => (
          <button key={opt.id} onClick={() => setVehicle({...vehicle, expansions: {...vehicle.expansions, [opt.id]: !((vehicle.expansions as any)[opt.id])}})} className={`w-full p-5 rounded-2xl border-2 transition-all flex items-center justify-between ${(vehicle.expansions as any)[opt.id] ? 'border-primary-500 bg-primary-500/5' : 'border-gray-100 dark:border-white/10'}`}>
            <div className="flex items-center gap-3">
              <opt.icon size={20} className={(vehicle.expansions as any)[opt.id] ? 'text-primary-500' : 'text-gray-400'}/>
              <div className="text-left">
                <p className="text-sm font-bold">{opt.label}</p>
                <p className="text-[0.65rem] text-gray-400 font-bold uppercase">{opt.rate}</p>
              </div>
            </div>
            <p className="text-sm font-black text-primary-500">+ Rp {opt.price.toLocaleString()}</p>
          </button>
        ))}

        <div className="p-6 rounded-3xl border-2 border-gray-100 dark:border-white/10 space-y-4">
          <div className="flex items-center gap-3 text-gray-500">
            <Scale size={20}/>
            <p className="text-sm font-black uppercase">TPL Limit Extension</p>
          </div>
          <div className="flex overflow-x-auto gap-2 no-scrollbar pb-2">
            {TPL_OPTIONS.map(opt => (
              <button 
                key={opt} onClick={() => setVehicle({...vehicle, expansions: {...vehicle.expansions, tpl: opt}})}
                className={`shrink-0 min-w-[70px] py-3 rounded-xl border-2 text-xs font-black transition-all ${vehicle.expansions.tpl === opt ? 'border-primary-500 bg-primary-500 text-white' : 'border-gray-100 dark:border-white/10 bg-white dark:bg-white/5'}`}
              >
                {opt > 0 ? `${opt}M` : 'None'}
              </button>
            ))}
          </div>
          <div className="flex justify-between items-center text-[0.65rem] font-bold">
            <span className="text-gray-400 uppercase tracking-widest">Estimated TPL Premium</span>
            <span className="text-primary-600 font-black">+ Rp { (vehicle.expansions.tpl * 10000).toLocaleString() }</span>
          </div>
        </div>
      </div>

      <div className="bg-gray-900 dark:bg-white text-white dark:text-black rounded-[2.5rem] p-8 space-y-6 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-10 opacity-5 dark:opacity-10"><DollarSign size={100}/></div>
        <h4 className="font-black text-lg uppercase tracking-tight border-b border-white/10 dark:border-black/10 pb-4">Premium Breakdown</h4>
        <div className="space-y-3 text-[0.7rem] font-bold uppercase tracking-widest opacity-80">
          <div className="flex justify-between"><span>Base Premium</span><span>Rp {pData.base.toLocaleString()}</span></div>
          {pData.floodCost > 0 && <div className="flex justify-between text-primary-400"><span>Flood Expansion</span><span>+ Rp {pData.floodCost.toLocaleString()}</span></div>}
          {pData.earthquakeCost > 0 && <div className="flex justify-between text-primary-400"><span>Earthquake</span><span>+ Rp {pData.earthquakeCost.toLocaleString()}</span></div>}
          {pData.srccCost > 0 && <div className="flex justify-between text-primary-400"><span>SRCC Extension</span><span>+ Rp {pData.srccCost.toLocaleString()}</span></div>}
          {pData.tplCost > 0 && <div className="flex justify-between text-primary-400"><span>TPL ({vehicle.expansions.tpl}M)</span><span>+ Rp {pData.tplCost.toLocaleString()}</span></div>}
          <div className="flex justify-between text-white dark:text-black pt-4 border-t border-white/10 dark:border-black/10">
             <span className="text-sm font-black">Net Premium</span>
             <span className="text-sm font-black">Rp {pData.total.toLocaleString()}</span>
          </div>
        </div>
        <button onClick={handleNext} className="w-full py-4 bg-primary-500 text-white rounded-2xl font-black uppercase tracking-widest text-[0.7rem] shadow-xl shadow-primary-500/30 active:scale-95 transition-all">
          Lanjut ke Upload Data
        </button>
      </div>
      <button onClick={handleBack} className="w-full py-4 border-2 border-gray-100 dark:border-white/10 rounded-2xl font-black uppercase tracking-widest text-xs">Ubah Kendaraan</button>
    </div>
  );

  const renderPersonalStep = () => (
    <div className="space-y-6 animate-fade-in max-w-md mx-auto w-full">
       <div className="space-y-2 text-center">
          <h3 className="text-2xl font-black">Identity Details</h3>
          <p className="text-xs text-gray-500">Provide official identity data for policy issuance.</p>
       </div>
       <div className="space-y-4">
          <div className="space-y-1">
             <label className="text-[0.65rem] font-black text-gray-400 uppercase tracking-widest ml-4">Full Name (per ID)</label>
             <input type="text" className="w-full p-4 rounded-2xl bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-white/10 outline-none focus:border-primary-500 font-bold" value={user.name} onChange={(e) => setUser({...user, name: e.target.value})} />
          </div>
          <div className="space-y-1">
             <label className="text-[0.65rem] font-black text-gray-400 uppercase tracking-widest ml-4">NIK / ID Number</label>
             <input type="text" className="w-full p-4 rounded-2xl bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-white/10 outline-none focus:border-primary-500 font-bold" value={user.ktp} onChange={(e) => setUser({...user, ktp: e.target.value.replace(/\D/g,'')})} />
          </div>
          <div className="space-y-1">
             <label className="text-[0.65rem] font-black text-gray-400 uppercase tracking-widest ml-4">Email Address</label>
             <input type="email" className="w-full p-4 rounded-2xl bg-gray-50 dark:bg-white/5 border border-gray-100 dark:border-white/10 outline-none focus:border-primary-500 font-bold" value={user.email} onChange={(e) => setUser({...user, email: e.target.value})} />
          </div>
          <button disabled={!user.name || !user.ktp || !user.email} onClick={handleNext} className="w-full py-5 bg-primary-500 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl active:scale-95 transition-all">Lanjut ke Photo Upload</button>
       </div>
    </div>
  );

  const renderAICheckStep = () => (
    <div className="space-y-6 animate-fade-in text-center pb-12 max-w-md mx-auto w-full">
      {loadingAI ? <Loader2 size={48} className="mx-auto text-primary-500 animate-spin" /> : <Zap size={48} className="mx-auto text-primary-500" />}
      <div className="space-y-2">
        <h3 className="text-2xl font-black">Neural AI Verification</h3>
        <p className="text-xs text-gray-500 max-w-xs mx-auto">Upload car photos for immediate audit. We check for surface quality and document legibility.</p>
      </div>

      <div className="grid grid-cols-2 gap-3 mt-8">
        {[
          { k: 'ktp', l: 'KTP' }, { k: 'stnkFront', l: 'STNK' }, 
          { k: 'carFront', l: 'Front' }, { k: 'carBack', l: 'Back' },
          { k: 'carLeft', l: 'Left' }, { k: 'carRight', l: 'Right' },
          { k: 'dashboard', l: 'Interior' }, { k: 'stnkBack', l: 'STNK 2' }
        ].map(item => (
          <div key={item.k} className="relative aspect-square border-2 border-dashed border-gray-200 dark:border-white/10 rounded-3xl flex flex-col items-center justify-center gap-2 overflow-hidden bg-white dark:bg-white/5 group">
            {(vehicle.photos as any)[item.k] ? (
              <>
                <img src={(vehicle.photos as any)[item.k]} className="w-full h-full object-cover" alt={item.l} />
                <button onClick={() => setVehicle({...vehicle, photos: {...vehicle.photos, [item.k]: null}})} className="absolute top-2 right-2 p-1.5 bg-white/90 rounded-full text-red-500 shadow-lg"><X size={18}/></button>
              </>
            ) : (
              <>
                <Camera size={24} className="text-gray-400 group-hover:text-primary-500 transition-colors" />
                <span className="text-[0.6rem] font-black uppercase text-gray-400 group-hover:text-primary-500 transition-colors">{item.l} Photo</span>
                <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => e.target.files?.[0] && handleFileUpload(item.k as any, e.target.files[0])} />
              </>
            )}
          </div>
        ))}
      </div>

      {aiError && (
        <div className="p-4 bg-red-50 dark:bg-red-900/20 text-red-600 rounded-2xl text-left flex items-start gap-3 border border-red-100 dark:border-red-500/20">
          <AlertTriangle size={18} className="shrink-0 mt-0.5" />
          <p className="text-xs font-bold leading-relaxed">{aiError}</p>
        </div>
      )}

      <button 
        onClick={handleVerifyAI} 
        disabled={loadingAI || uploadSuccess} 
        className="w-full py-5 bg-primary-500 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl flex items-center justify-center gap-2 transition-all active:scale-95"
      >
        {loadingAI ? <Loader2 size={18} className="animate-spin" /> : <ShieldCheck size={18}/>}
        {uploadSuccess ? 'Verification Success' : 'Start Audit Engine'}
      </button>
    </div>
  );

  const renderPaymentStep = () => (
    <div className="space-y-6 animate-fade-in max-w-md mx-auto w-full">
       <div className="space-y-2 text-center">
          <h3 className="text-2xl font-black">Select Payment</h3>
          <p className="text-xs text-gray-500">Secure your policy via instant payment nodes.</p>
       </div>

       <div className="bg-white dark:bg-white/5 rounded-[2.5rem] p-6 border border-gray-100 dark:border-white/10 shadow-sm space-y-4">
          <div className="flex justify-between items-center text-xs font-black uppercase text-gray-400 tracking-widest border-b dark:border-white/5 pb-3">
             <span>Premium Total</span>
             <span className="text-primary-500 font-black">Rp { (pData.total + STAMP_DUTY + 50000).toLocaleString() }</span>
          </div>

          <div className="grid grid-cols-1 gap-3">
             {[
               { id: 'va', label: 'Virtual Account', icon: LayoutDashboard, sub: 'BCA, Mandiri, BNI' },
               { id: 'qris', label: 'QRIS Scan & Pay', icon: Smartphone, sub: 'Dana, OVO, GoPay' },
               { id: 'cc', label: 'Credit Card 0%', icon: CreditCard, sub: 'VISA, Mastercard' },
             ].map(m => (
               <button 
                  key={m.id} onClick={() => setPaymentMethod(m.id)}
                  className={`flex items-center justify-between p-5 rounded-2xl border-2 transition-all ${paymentMethod === m.id ? 'border-primary-500 bg-primary-500/5' : 'border-gray-100 dark:border-white/5 bg-white dark:bg-white/5'}`}
               >
                  <div className="flex items-center gap-4">
                     <div className={`p-2 rounded-xl transition-colors ${paymentMethod === m.id ? 'bg-primary-500 text-white' : 'bg-gray-100 dark:bg-white/10 text-gray-500'}`}><m.icon size={20}/></div>
                     <div className="text-left">
                        <span className="block text-sm font-black uppercase leading-none">{m.label}</span>
                        <span className="text-[0.6rem] text-gray-400 font-bold uppercase">{m.sub}</span>
                     </div>
                  </div>
                  {paymentMethod === m.id && <CheckCircle2 size={18} className="text-primary-500" />}
               </button>
             ))}
          </div>
       </div>

       <button disabled={!paymentMethod} onClick={handlePayment} className="w-full py-5 bg-gray-900 dark:bg-white text-white dark:text-black rounded-[2rem] font-black uppercase tracking-widest shadow-xl flex items-center justify-center gap-2 active:scale-95 transition-all">
          <Lock size={18}/> Pay Securely
       </button>
    </div>
  );

  const renderSuccessStep = () => (
    <div className="text-center space-y-8 py-12 animate-pop-in relative overflow-hidden max-w-md mx-auto w-full">
       <div className="absolute inset-0 pointer-events-none">
          <div className="confetti-piece left-[10%] animate-confetti animation-delay-2000"></div>
          <div className="confetti-piece left-[40%] animate-confetti animation-delay-4000"></div>
          <div className="confetti-piece left-[70%] animate-confetti"></div>
          <div className="confetti-piece left-[90%] animate-confetti animation-delay-2000"></div>
       </div>

       <div className="w-28 h-28 bg-emerald-500 rounded-full flex items-center justify-center mx-auto shadow-2xl shadow-emerald-500/30 animate-pop-in relative z-10">
          <Check size={64} strokeWidth={4} className="text-white" />
       </div>

       <div className="space-y-3 relative z-10">
          <h2 className="text-4xl font-black tracking-tighter">Policy Active!</h2>
          <p className="text-sm text-gray-500 dark:text-gray-400 max-w-xs mx-auto">Your engine is now shielded. Digital policy sent to <strong>{user.email}</strong>.</p>
       </div>

       <div className="bg-gray-50 dark:bg-white/5 rounded-[2.5rem] p-6 border border-gray-100 dark:border-white/10 text-left space-y-4 shadow-sm">
          <div className="flex justify-between items-center">
             <span className="text-[0.6rem] font-black text-gray-400 uppercase tracking-[0.2em]">Ref Code</span>
             <span className="text-xs font-mono font-black text-primary-500">SP-{Date.now().toString().slice(-6)}</span>
          </div>
          <div className="flex justify-between items-center">
             <span className="text-[0.6rem] font-black text-gray-400 uppercase tracking-[0.2em]">Valid Thru</span>
             <span className="text-xs font-black">Jan 2026</span>
          </div>
       </div>

       <button onClick={() => setPage('home')} className="w-full py-5 bg-primary-500 text-white rounded-[2rem] font-black uppercase tracking-widest text-xs shadow-xl active:scale-95 transition-all">
          Dashboard Home
       </button>
    </div>
  );

  return (
    <div className="max-w-4xl mx-auto p-6 min-h-[80vh] flex flex-col justify-center">
       {step < 7 && (
         <div className="flex items-center gap-4 mb-8 max-w-md mx-auto w-full">
            <button onClick={handleBack} disabled={step === 1} className="p-2 bg-gray-100 dark:bg-white/5 rounded-xl disabled:opacity-30 transition-all"><ChevronLeft size={20} /></button>
            <div className="flex-1 bg-gray-100 dark:bg-white/5 h-2 rounded-full overflow-hidden">
               <div className="bg-primary-500 h-full transition-all duration-700" style={{width: `${(step/7)*100}%`}}></div>
            </div>
            <span className="text-[0.65rem] font-black text-gray-400">{step}/7</span>
         </div>
       )}

       {step === 1 && renderVehicleStep()}
       {step === 2 && renderCoverageStep()}
       {step === 3 && renderPersonalStep()}
       {step === 4 && renderAICheckStep()}
       {step === 5 && (
          <div className="space-y-6 animate-fade-in text-center max-w-md mx-auto w-full">
             <div className="w-16 h-16 bg-primary-500/10 rounded-full flex items-center justify-center mx-auto mb-2"><Sparkles size={32} className="text-primary-500"/></div>
