       </div>

       <button onClick={() => setPage('home')} className="w-full py-5 bg-primary-500 text-white rounded-[2rem] font-black uppercase tracking-widest text-xs shadow-xl active:scale-95 transition-all">
          Dashboard Home
       </button>
    </div>
  );

  return (
    <div className="max-w-4xl mx-auto p-6 min-h-[80vh] flex flex-col justify-center">
       {step < 7 && (
         <div className="flex items-center gap-4 mb-8 max-w-md mx-auto w-full">
            <button onClick={handleBack} disabled={step === 1} className="p-2 bg-gray-100 dark:bg-white/5 rounded-xl disabled:opacity-30 transition-all"><ChevronLeft size={20} /></button>
            <div className="flex-1 bg-gray-100 dark:bg-white/5 h-2 rounded-full overflow-hidden">
               <div className="bg-primary-500 h-full transition-all duration-700" style={{width: `${(step/7)*100}%`}}></div>
            </div>
            <span className="text-[0.65rem] font-black text-gray-400">{step}/7</span>
         </div>
       )}

       {step === 1 && renderVehicleStep()}
       {step === 2 && renderCoverageStep()}
       {step === 3 && renderPersonalStep()}
       {step === 4 && renderAICheckStep()}
       {step === 5 && (
          <div className="space-y-6 animate-fade-in text-center max-w-md mx-auto w-full">
             <div className="w-16 h-16 bg-primary-500/10 rounded-full flex items-center justify-center mx-auto mb-2"><Sparkles size={32} className="text-primary-500"/></div>
             <h3 className="text-2xl font-black">Application Verified</h3>
             <div className="bg-gray-50 dark:bg-white/5 p-6 rounded-[2.5rem] border border-gray-100 dark:border-white/10 space-y-4 text-left shadow-sm">
                <div className="flex justify-between border-b dark:border-white/5 pb-2"><span className="text-[0.6rem] font-bold text-gray-400 uppercase tracking-widest">Customer</span><span className="text-xs font-bold uppercase">{user.name}</span></div>
                <div className="flex justify-between border-b dark:border-white/5 pb-2"><span className="text-[0.6rem] font-bold text-gray-400 uppercase tracking-widest">Vehicle</span><span className="text-xs font-bold uppercase">{vehicle.brand} {vehicle.modelCode}</span></div>
                <div className="flex justify-between items-center pt-2">
                   <span className="text-sm font-black uppercase tracking-tighter">Total Due</span>
                   <span className="text-2xl font-black text-primary-500">Rp { (pData.total + STAMP_DUTY + 55000).toLocaleString() }</span>
                </div>
             </div>
             <button onClick={handleNext} className="w-full py-4 bg-primary-500 text-white rounded-2xl font-black uppercase text-xs shadow-lg shadow-primary-500/20 active:scale-95 transition-all">Proceed to Settlement</button>
          </div>
       )}
       {step === 6 && renderPaymentStep()}
       {step === 7 && renderSuccessStep()}
    </div>
  );
};

// --- MAIN APP ENTRY ---

function App() {
  const [lang, setLang] = useState<Language>(Language.ID); 
  const [darkMode, setDarkMode] = useState(true);
  const [currentPage, setPage] = useState('home');
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsLoading(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (darkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [darkMode]);

  const changePage = (page: string) => {
    if (page === currentPage) return;
    setIsLoading(true);
    setTimeout(() => { setPage(page); setIsLoading(false); }, 800);
  };

  const renderContent = () => {
    switch (currentPage) {
      case 'home': return <HomeScreen setPage={changePage} lang={lang} />;
      case 'products': return <ProductsScreen setPage={changePage} lang={lang} />;
      case 'car-wizard': return <CarInsuranceWizard setPage={changePage} />;
      case 'claim': return <ClaimScreen />;
      case 'about': return <AboutScreen lang={lang} />;
      case 'console': return <ConsoleScreen lang={lang} />;
      default: return <HomeScreen setPage={changePage} lang={lang} />;
    }
  };

  return (
    <div className="h-screen w-screen bg-white dark:bg-[#050505] text-gray-900 dark:text-white flex flex-col font-sans transition-colors duration-500 overflow-hidden">
      {isLoading && <WalkingLoader />}
      {!isAuthenticated && !isLoading ? (
        <AuthScreen onLogin={() => setIsAuthenticated(true)} />
      ) : (
        <>
          <AppHeader lang={lang} setLang={setLang} darkMode={darkMode} setDarkMode={setDarkMode} onLogout={() => setIsAuthenticated(false)} />
          <main className="flex-1 mt-16 mb-20 overflow-y-auto no-scrollbar">{renderContent()}</main>
          <BottomNav active={currentPage} setPage={changePage} lang={lang} />
        </>
      )}
    </div>
  );
}

