// --- MAIN APP ENTRY ---

function App() {
  const [lang, setLang] = useState<Language>(Language.ID); 
  const [darkMode, setDarkMode] = useState(true);
  const [currentPage, setPage] = useState('home');
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsLoading(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (darkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [darkMode]);

  const changePage = (page: string) => {
    if (page === currentPage) return;
    setIsLoading(true);
    setTimeout(() => { setPage(page); setIsLoading(false); }, 1000);
  };

  const renderContent = () => {
    switch (currentPage) {
      case 'home': return <HomeScreen setPage={changePage} lang={lang} />;
      case 'products': return <ProductsScreen setPage={changePage} lang={lang} />;
      case 'car-wizard': return <CarInsuranceWizard lang={lang} setPage={changePage} />;
      case 'claim': return <ClaimScreen lang={lang} setPage={changePage} />;
      case 'about': return <AboutScreen lang={lang} />;
      case 'console': return <ConsoleScreen lang={lang} />;
      default: return <HomeScreen setPage={changePage} lang={lang} />;
    }
  };

  return (
    <div className="h-screen w-screen bg-white dark:bg-[#050505] text-gray-900 dark:text-white flex flex-col font-sans transition-colors duration-500 overflow-hidden">
      {isLoading && <WalkingLoader />}
      {!isAuthenticated && !isLoading ? (
        <AuthScreen onLogin={() => setIsAuthenticated(true)} lang={lang} />
      ) : (
        <>
          <AppHeader lang={lang} darkMode={darkMode} setDarkMode={setDarkMode} onLogout={() => setIsAuthenticated(false)} />
          <main className="flex-1 mt-16 mb-20 overflow-y-auto no-scrollbar">{renderContent()}</main>
          <BottomNav active={currentPage} setPage={changePage} />
        </>
      )}
    </div>
  );
}

export default App;

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface ClaimPart {
  namaPart: string;
  kondisi: string;
  tindakan: 'Perbaiki' | 'Ganti';
  estimasiBiaya: number;
}

export interface ClaimAnalysisResult {
  success: boolean;
  data?: {
    severity: 'Ringan' | 'Sedang' | 'Berat' | 'Total Loss';
    totalEstimasi: number;
    rincianPart: ClaimPart[];
    aiInsight: string;
    rekomendasiBengkel: string;
  };
  error?: string;
}

export const analyzeClaimPhoto = async (base64Image: string): Promise<ClaimAnalysisResult> => {
  const modelId = 'gemini-3-pro-preview';
  const prompt = `Analisa kerusakan kendaraan dari foto ini untuk klaim asuransi. 
  Berikan hasil analisa dalam Bahasa Indonesia dengan format JSON yang sangat mendetail:
  {
    "severity": "Ringan" | "Sedang" | "Berat",
    "totalEstimasi": number (total biaya dalam Rupiah tanpa titik/koma),
    "rincianPart": [
      {
        "namaPart": "nama komponen",
        "kondisi": "deskripsi kerusakan",
        "tindakan": "Perbaiki" | "Ganti",
        "estimasiBiaya": number (biaya per part)
      }
    ],
    "aiInsight": "penjelasan singkat mengenai penyebab kerusakan berdasarkan visual",
    "rekomendasiBengkel": "saran jenis bengkel (Umum/Resmi)"
  }
  Gunakan logika estimasi biaya bengkel di Indonesia.`;

  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: [{ text: prompt }, { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }] },
      config: { responseMimeType: "application/json" }
    });

    const text = response.text;
    if (!text) return { success: false, error: "AI gagal membaca gambar." };

    return { success: true, data: JSON.parse(text) };
  } catch (error) {
    console.error("Claim Analysis Error:", error);
    return { success: false, error: "Layanan Analisa AI sedang sibuk." };
  }
};

export interface PhotoScore {
  label: string;
  score: number;
  clarity: number;
  angle: number;
  lighting: number;
  status: 'valid' | 'invalid';
  remarks: string;
}

export interface AnalysisResult {
  success: boolean;
  data?: {
    overallScore: number;
    photoScores: PhotoScore[];
    dataMatch: {
      brandMatch: boolean;
      yearMatch: boolean;
      plateMatch: boolean;
    };
    insights: string;
  };
  error?: string;
}

export const analyzeVehiclePhotos = async (
  photos: { label: string, data: string }[], 
  inputData: { brand: string, model: string, year: number, plate: string }
): Promise<AnalysisResult> => {
  const modelId = 'gemini-3-pro-preview';
  const prompt = `Verify these vehicle photos against this data: Brand: ${inputData.brand}, Model: ${inputData.model}, Year: ${inputData.year}, Plate: ${inputData.plate}. Return JSON: {"overallScore": number, "photoScores": [...], "dataMatch": {...}, "insights": "string"}`;

  try {
    const parts: any[] = [{ text: prompt }];
    photos.forEach(p => {
      const cleanBase64 = p.data.includes(',') ? p.data.split(',')[1] : p.data;
      parts.push({ inlineData: { mimeType: "image/jpeg", data: cleanBase64 } });
    });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: parts },
      config: { responseMimeType: "application/json" }
    });

    return { success: true, data: JSON.parse(response.text || '{}') };
  } catch (error) {
    return { success: false };
  }
};

export const analyzeVehiclePhoto = async (base64Images: string[], labels: string[]) => {
    const photos = labels.map((l, i) => ({ label: l, data: base64Images[i] }));
    return analyzeVehiclePhotos(photos, { brand: 'Unknown', model: 'Unknown', year: 0, plate: 'Unknown' });
};

