import { GoogleGenAI } from "@google/genai";

export interface ClaimPart {
  namaPart: string;
  kondisi: string;
  tindakan: 'Perbaiki' | 'Ganti';
  estimasiBiaya: number;
}

export interface ClaimAnalysisData {
  severity: 'Ringan' | 'Sedang' | 'Berat' | 'Total Loss';
  totalEstimasi: number;
  rincianPart: ClaimPart[];
  aiInsight: string;
  rekomendasiBengkel: string;
}

export const analyzeClaimPhoto = async (base64Image: string): Promise<{ success: boolean; data?: ClaimAnalysisData; error?: string }> => {
  // Inisialisasi di dalam fungsi sesuai regulasi terbaru
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelId = 'gemini-3-flash-preview';

  const prompt = `Analisa kerusakan kendaraan dari foto ini untuk klaim asuransi. 
  Berikan hasil analisa dalam Bahasa Indonesia dengan format JSON mendetail:
  {
    "severity": "Ringan" | "Sedang" | "Berat" | "Total Loss",
    "totalEstimasi": number (total biaya dalam Rupiah, angka saja),
    "rincianPart": [
      {
        "namaPart": "nama komponen yang rusak",
        "kondisi": "deskripsi visual kerusakan",
        "tindakan": "Perbaiki" | "Ganti",
        "estimasiBiaya": number (biaya per part)
      }
    ],
    "aiInsight": "penjelasan singkat mengenai dampak benturan",
    "rekomendasiBengkel": "Tipe bengkel yang disarankan"
  }`;

  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: [{ text: prompt }, { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }] },
      config: { responseMimeType: "application/json" }
    });

    if (!response.text) throw new Error("No response from AI");
    return { success: true, data: JSON.parse(response.text) };
  } catch (error) {
    console.error("AI Analysis Error:", error);
    return { success: false, error: "Gagal menganalisa. Mohon coba lagi." };
  }
};

export const analyzeVehiclePhoto = async (base64Images: string[], labels: string[]) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const modelId = 'gemini-3-pro-preview';
    const prompt = `Lakukan audit visual terhadap foto kendaraan ini. Berikan skor kualitas 1-100 dan deteksi jika ada kerusakan pra-polis. Return JSON: {"overallScore": number, "insights": "string"}`;

    try {
        const parts = [{ text: prompt }];
        base64Images.forEach(img => {
            const data = img.includes(',') ? img.split(',')[1] : img;
            parts.push({ inlineData: { mimeType: "image/jpeg", data } } as any);
        });

        const response = await ai.models.generateContent({
            model: modelId,
            contents: { parts },
            config: { responseMimeType: "application/json" }
        });

        return { success: true, data: JSON.parse(response.text || '{}') };
    } catch (e) {
        return { success: false, error: "Audit gagal." };
    }
};

