const ClaimScreen = ({ setPage }: { setPage: (p: string) => void }) => {
  const [image, setImage] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<ClaimAnalysisData | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      setImage(reader.result as string);
      startAI(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const startAI = async (imgData: string) => {
    setAnalyzing(true);
    setResult(null);
    const res = await analyzeClaimPhoto(imgData);
    if (res.success && res.data) {
      setResult(res.data);
    } else {
      alert("AI gagal menganalisa. Pastikan foto cukup terang.");
      setImage(null);
    }
    setAnalyzing(false);
  };

  return (
    <div className="p-6 space-y-6 max-w-lg mx-auto pb-32 animate-fade-in">
      <div className="flex items-center gap-3">
          <button onClick={() => setPage('home')} className="p-2 bg-gray-100 dark:bg-white/5 rounded-xl"><ChevronLeft size={20}/></button>
          <h2 className="text-2xl font-black">Klaim <span className="text-primary-500">AI</span></h2>
      </div>

      {!image ? (
        <div className="space-y-6">
          <div 
            onClick={() => fileRef.current?.click()}
            className="aspect-video border-2 border-dashed border-gray-200 dark:border-white/10 rounded-[2.5rem] bg-white dark:bg-white/5 flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-primary-500 transition-all group"
          >
            <div className="w-16 h-16 bg-gray-50 dark:bg-white/5 rounded-full flex items-center justify-center text-gray-400 group-hover:text-primary-500 transition-colors">
                <Camera size={32}/>
            </div>
            <p className="font-bold text-gray-500">Ambil Foto Kerusakan</p>
            <input ref={fileRef} type="file" accept="image/*" capture="environment" className="hidden" onChange={handleFile} />
          </div>

          <div className="bg-blue-50 dark:bg-blue-900/10 p-5 rounded-3xl flex gap-4 border border-blue-100 dark:border-blue-800/30">
            <Info className="text-blue-500 shrink-0" size={24} />
            <p className="text-xs text-blue-700 dark:text-blue-400 leading-relaxed font-semibold">Gunakan kamera langsung untuk hasil terbaik. Pastikan seluruh area yang penyok atau lecet terlihat jelas.</p>
          </div>
        </div>
      ) : (
        <div className="space-y-6">
          <div className="relative aspect-video rounded-[2.5rem] overflow-hidden shadow-2xl border-4 border-white dark:border-white/5">
            <img src={image} className="w-full h-full object-cover" alt="claim" />
            {analyzing && (
              <div className="absolute inset-0 bg-black/40 backdrop-blur-[2px]">
                 <div className="scanning-line absolute top-0 w-full"></div>
                 <div className="absolute inset-0 flex items-center justify-center">
                    <div className="bg-white/90 dark:bg-black/80 px-6 py-3 rounded-full flex items-center gap-3 shadow-xl">
                        <Loader2 className="animate-spin text-primary-500" size={18} />
                        <span className="text-xs font-black uppercase tracking-widest">SurePath Neural Processing...</span>
                    </div>
                 </div>
              </div>
            )}
            {!analyzing && (
                <button onClick={() => setImage(null)} className="absolute top-4 right-4 p-2 bg-black/60 text-white rounded-full"><X size={18}/></button>
            )}
          </div>

          {analyzing && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                  <div className="bg-gray-100 dark:bg-white/5 animate-pulse h-16 rounded-2xl"></div>
                  <div className="bg-gray-100 dark:bg-white/5 animate-pulse h-16 rounded-2xl"></div>
              </div>
              <SkeletonItem />
              <SkeletonItem />
            </div>
          )}

          {result && (
            <div className="space-y-6 animate-fade-in">
                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-white dark:bg-white/5 p-4 rounded-3xl border border-gray-100 dark:border-white/10 shadow-sm">
                        <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest mb-1">Keparahan</p>
                        <div className="flex items-center gap-2">
                            <div className={`w-2 h-2 rounded-full ${result.severity === 'Ringan' ? 'bg-emerald-500' : 'bg-red-500'}`}></div>
                            <span className="font-black">{result.severity}</span>
                        </div>
                    </div>
                    <div className="bg-primary-500 p-4 rounded-3xl shadow-lg shadow-primary-500/20 text-white">
                        <p className="text-[0.6rem] font-black opacity-80 uppercase tracking-widest mb-1">Total Estimasi</p>
                        <span className="text-lg font-black">{formatIDR(result.totalEstimasi)}</span>
                    </div>
                </div>

                <div className="space-y-3">
                    <h3 className="text-xs font-black uppercase text-gray-400 tracking-widest ml-2">Analisa Part</h3>
                    {result.rincianPart.map((p, i) => (
                        <div key={i} className="bg-white dark:bg-white/5 p-4 rounded-2xl border border-gray-100 dark:border-white/10 flex items-center justify-between">
