                                    <p className="text-sm font-bold uppercase">{p.namaPart}</p>
                                    <p className="text-[0.65rem] text-gray-400">{p.kondisi}</p>
                                </div>
                            </div>
                            <div className="text-right">
                                <p className="text-xs font-black">{formatIDR(p.estimasiBiaya)}</p>
                                <span className={`text-[0.5rem] font-black px-2 py-0.5 rounded-md uppercase ${p.tindakan === 'Ganti' ? 'bg-red-500 text-white' : 'bg-emerald-500 text-white'}`}>{p.tindakan}</span>
                            </div>
                        </div>
                    ))}
                </div>

                <div className="bg-gray-100 dark:bg-white/5 p-6 rounded-3xl border border-gray-200 dark:border-white/10 italic text-sm text-gray-500 dark:text-gray-400 leading-relaxed">
                    <Sparkles size={16} className="text-primary-500 mb-2" />
                    "{result.aiInsight}"
                </div>

                <button className="w-full py-5 bg-primary-500 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl shadow-primary-500/30 active:scale-95 transition-all">
                    Ajukan Klaim Sekarang
                </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

