const App = () => {
  const [currentPage, setPage] = useState('home');
  const [darkMode, setDarkMode] = useState(true);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const timer = setTimeout(() => setLoading(false), 1500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (darkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [darkMode]);

  if (loading) return (
    <div className="fixed inset-0 bg-white dark:bg-black flex flex-col items-center justify-center">
        <div className="w-20 h-20 bg-primary-500 rounded-[2rem] animate-bounce flex items-center justify-center text-white shadow-2xl">
            <Zap size={40} />
        </div>
        <p className="mt-6 font-black uppercase tracking-[0.3em] text-xs text-primary-500 animate-pulse">SurePath AI</p>
    </div>
  );

  const renderContent = () => {
    switch (currentPage) {
      case 'home': return <HomeScreen setPage={setPage}/>;
      case 'claim': return <ClaimScreen setPage={setPage}/>;
      case 'profile': return <ProfileScreen />;
      case 'products': 
        return (
          <div className="p-8 text-center space-y-4 max-w-lg mx-auto">
              <h2 className="text-3xl font-black">Produk Kami</h2>
              <div className="p-10 bg-white dark:bg-white/5 rounded-[3rem] border border-dashed border-gray-200 dark:border-white/10">
                  <p className="text-gray-400">Daftar produk asuransi retail akan tampil di sini.</p>
              </div>
              <button onClick={() => setPage('home')} className="font-bold text-primary-500">Kembali</button>
          </div>
        );
      case 'console':
        return (
          <div className="p-8 text-center space-y-4 max-w-lg mx-auto">
              <h2 className="text-3xl font-black">Konsol Mitra</h2>
              <div className="bg-emerald-500/10 p-8 rounded-3xl text-emerald-600 font-bold">
                  Akses Khusus Agen & Partner
              </div>
              <button onClick={() => setPage('home')} className="font-bold text-primary-500">Kembali</button>
          </div>
        );
      default: return <HomeScreen setPage={setPage}/>;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-dark-bg transition-colors duration-500 overflow-x-hidden">
      {/* Header */}
      <header className="fixed top-0 inset-x-0 h-20 bg-white/80 dark:bg-black/80 backdrop-blur-xl z-40 border-b border-gray-100 dark:border-white/5 px-6 flex items-center justify-between">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setPage('home')}>
              <div className="w-10 h-10 bg-primary-500 rounded-xl flex items-center justify-center text-white"><ShieldCheck size={22}/></div>
              <span className="text-xl font-black tracking-tighter uppercase">Sure<span className="text-primary-500">Path</span></span>
          </div>
          <button onClick={() => setDarkMode(!darkMode)} className="p-3 bg-gray-100 dark:bg-white/5 rounded-2xl transition-colors">
              {darkMode ? <Sun size={20}/> : <Moon size={20}/>}
          </button>
      </header>

      {/* Content */}
      <main className="pt-24 pb-20">
          {renderContent()}
      </main>

      {/* Bottom Nav */}
      <nav className="fixed bottom-0 inset-x-0 h-20 bg-white/90 dark:bg-black/90 backdrop-blur-2xl border-t border-gray-100 dark:border-white/5 z-50 flex items-center justify-around px-4">
          {[
              { id: 'home', icon: Home, label: 'Beranda' },
              { id: 'products', icon: Grid, label: 'Produk' },
              { id: 'claim', icon: Zap, label: 'Klaim AI' },
              { id: 'profile', icon: User, label: 'Profil' },
              { id: 'console', icon: Briefcase, label: 'Mitra' }
          ].map(item => (
              <button 
                  key={item.id} 
                  onClick={() => setPage(item.id)}
                  className={`flex flex-col items-center gap-1 transition-all ${currentPage === item.id ? 'text-primary-500' : 'text-gray-400'}`}
              >
                  <div className={`p-2 rounded-xl transition-all ${currentPage === item.id ? 'bg-primary-500/10' : ''}`}><item.icon size={22} /></div>
                  <span className="text-[0.6rem] font-bold uppercase tracking-wider">{item.label}</span>
              </button>
          ))}
      </nav>
    </div>
  );
};

