const ClaimScreen = ({ setPage }: { setPage: (p: string) => void }) => {
  const [image, setImage] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<ClaimAnalysisData | null>(null);
  const [flowStep, setFlowStep] = useState<'photo' | 'incident'>('photo');

  const cameraInputRef = useRef<HTMLInputElement>(null);

  const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      setImage(reader.result as string);
      startAI(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const startAI = async (imgData: string) => {
    setAnalyzing(true);
    setResult(null);
    const res = await analyzeClaimPhoto(imgData);
    if (res.success && res.data) {
      setResult(res.data);
    } else {
      alert("AI gagal menganalisa. Mohon coba lagi.");
      setImage(null);
    }
    setAnalyzing(false);
  };

  return (
    <div className="p-6 space-y-6 max-w-lg mx-auto pb-32 animate-fade-in">
      {flowStep === 'photo' ? (
        <>
          <div className="flex items-center gap-3">
              <button onClick={() => setPage('home')} className="p-2 bg-gray-100 dark:bg-white/5 rounded-xl"><ChevronLeft size={20}/></button>
              <h2 className="text-2xl font-black">Klaim <span className="text-primary-500">AI</span></h2>
          </div>

          {!image ? (
            <div className="space-y-6">
              <div 
                onClick={() => cameraInputRef.current?.click()}
                className="aspect-[4/3] border-2 border-dashed border-gray-200 dark:border-white/10 rounded-[2.5rem] bg-white dark:bg-white/5 flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-primary-500 transition-all group overflow-hidden relative"
              >
                <div className="w-20 h-20 bg-gray-50 dark:bg-white/5 rounded-full flex items-center justify-center text-gray-400 group-hover:text-primary-500 transition-colors">
                    <Camera size={40}/>
                </div>
                <div className="text-center">
                    <p className="font-black text-lg uppercase tracking-tight">Snap Damage Photo</p>
                    <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Automatic Neural Detection</p>
                </div>
                <input ref={cameraInputRef} type="file" accept="image/*" capture="environment" className="hidden" onChange={handleFile} />
              </div>
              <div className="bg-blue-500/10 p-6 rounded-[2rem] flex gap-4 border border-blue-500/20">
                <Info className="text-blue-500 shrink-0" size={20} />
                <p className="text-xs text-blue-700 dark:text-blue-300 leading-relaxed font-bold uppercase tracking-wide">
                  Gunakan pencahayaan cukup dan hindari pantulan cahaya pada cat kendaraan untuk hasil diagnosa maksimal.
                </p>
              </div>
            </div>
          ) : (
            <div className="space-y-6">
              <div className="relative aspect-video rounded-[2.5rem] overflow-hidden shadow-2xl border-4 border-white dark:border-white/10">
                <img src={image} className="w-full h-full object-cover" alt="claim" />
                {analyzing && (
                  <div className="absolute inset-0 bg-black/60 backdrop-blur-[4px] flex flex-col items-center justify-center">
                    <div className="scanning-line absolute top-0 w-full"></div>
                    <div className="w-12 h-12 border-4 border-primary-500 border-t-transparent rounded-full animate-spin mb-4" />
                    <span className="text-[0.65rem] font-black uppercase tracking-[0.3em] text-white">SurePath Neural Analysis...</span>
                  </div>
                )}
                {!analyzing && (
                    <button onClick={() => {setImage(null); setResult(null);}} className="absolute top-4 right-4 p-2 bg-black/60 text-white rounded-full"><X size={18}/></button>
                )}
              </div>

              {result && (
                <div className="space-y-6 animate-fade-in">
                    <div className="grid grid-cols-2 gap-4">
                        <div className="bg-white dark:bg-white/5 p-5 rounded-[2rem] border border-gray-100 dark:border-white/10">
                            <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest mb-1">Status</p>
                            <span className="font-black text-lg text-primary-500 uppercase">{result.severity}</span>
                        </div>
                        <div className="bg-primary-500 p-5 rounded-[2rem] text-white shadow-lg shadow-primary-500/20">
                            <p className="text-[0.6rem] font-black opacity-80 uppercase tracking-widest mb-1">Estimasi Biaya</p>
                            <span className="text-lg font-black">{formatIDR(result.totalEstimasi)}</span>
                        </div>
                    </div>

                    <div className="space-y-3">
                        <h3 className="text-xs font-black uppercase text-gray-400 tracking-widest ml-2">Analisa Neural</h3>
                        {result.rincianPart.map((p, i) => (
                            <div key={i} className="bg-white dark:bg-white/5 p-4 rounded-2xl border border-gray-100 dark:border-white/10 flex items-center justify-between">
                                <div className="flex items-center gap-4">
                                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${p.tindakan === 'Ganti' ? 'bg-red-500/10 text-red-500' : 'bg-emerald-500/10 text-emerald-500'}`}>
