                    <button 
                      onClick={() => setFlowStep('incident')}
                      className="w-full py-5 bg-primary-500 text-white rounded-[2rem] font-black uppercase tracking-widest text-xs flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"
                    >
                      Lanjutkan Data Kejadian <ArrowRight size={18}/>
                    </button>
                </div>
              )}
            </div>
          )}
        </>
      ) : (
        <IncidentDataScreen 
          onBack={() => setFlowStep('photo')} 
          onComplete={() => {
            alert("Laporan Klaim Berhasil Dikirim!");
            setPage('home');
            setFlowStep('photo');
            setImage(null);
            setResult(null);
          }} 
        />
      )}
    </div>
  );
};

