const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentPage, setPage] = useState('home');
  const [darkMode, setDarkMode] = useState(true);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const timer = setTimeout(() => setLoading(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (darkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [darkMode]);

  if (loading) return (
    <div className="fixed inset-0 bg-[#030303] flex flex-col items-center justify-center z-[100]">
        <LaserBackground />
        <div className="w-20 h-20 bg-primary-500 rounded-[2rem] animate-pulse flex items-center justify-center text-white shadow-[0_0_40px_rgba(16,185,129,0.4)]">
            <Zap size={40} />
        </div>
        <p className="mt-8 font-black uppercase tracking-[0.4em] text-[0.65rem] text-primary-500 animate-fade-in">System Initialization...</p>
    </div>
  );

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-dark-bg relative overflow-hidden">
        <LaserBackground />
        <LoginPortal 
          onLogin={() => setIsLoggedIn(true)} 
          onQuickClaim={() => { setIsLoggedIn(true); setPage('claim'); }} 
        />
      </div>
    );
  }

  const renderContent = () => {
    switch (currentPage) {
      case 'home': return <HomeScreen setPage={setPage}/>;
      case 'claim': return <ClaimScreen setPage={setPage}/>;
      case 'products': 
        return (
          <div className="p-8 text-center space-y-4 max-w-lg mx-auto relative z-10">
              <h2 className="text-3xl font-black">Produk Kami</h2>
              <div className="p-12 bg-white dark:bg-white/5 rounded-[3rem] border border-dashed border-gray-200 dark:border-white/10">
                  <p className="text-gray-400 font-bold uppercase tracking-widest text-xs">Produk Retail coming soon</p>
              </div>
              <button onClick={() => setPage('home')} className="font-black text-xs uppercase tracking-widest text-primary-500">Back Home</button>
          </div>
        );
      default: return <HomeScreen setPage={setPage}/>;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-dark-bg transition-colors duration-500 relative">
      <LaserBackground />
      {/* Header */}
      <header className="fixed top-0 inset-x-0 h-20 bg-white/80 dark:bg-black/40 backdrop-blur-xl z-40 border-b border-gray-100 dark:border-white/5 px-6 flex items-center justify-between">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setPage('home')}>
              <div className="w-10 h-10 bg-primary-500 rounded-xl flex items-center justify-center text-white"><ShieldCheck size={22}/></div>
              <span className="text-xl font-black tracking-tighter uppercase">Sure<span className="text-primary-500">Path</span></span>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={() => setDarkMode(!darkMode)} className="p-3 bg-gray-100 dark:bg-white/5 rounded-2xl">
                {darkMode ? <Sun size={18}/> : <Moon size={18}/>}
            </button>
            <button onClick={() => setIsLoggedIn(false)} className="p-3 bg-red-500/10 text-red-500 rounded-2xl">
                <LogOut size={18}/>
            </button>
          </div>
      </header>

      {/* Content */}
      <main className="pt-24 pb-28">
          {renderContent()}
      </main>

      {/* Bottom Nav */}
      <nav className="fixed bottom-6 inset-x-6 h-20 bg-white/90 dark:bg-black/60 backdrop-blur-2xl border border-gray-100 dark:border-white/10 z-50 flex items-center justify-around px-4 rounded-[2.5rem] shadow-2xl">
          {[
              { id: 'home', icon: Home, label: 'Portal' },
              { id: 'products', icon: Grid, label: 'Store' },
              { id: 'claim', icon: Zap, label: 'Claim' },
              { id: 'profile', icon: User, label: 'Profile' },
              { id: 'console', icon: Briefcase, label: 'Agent' }
          ].map(item => (
              <button 
                  key={item.id} 
                  onClick={() => setPage(item.id)}
                  className={`flex flex-col items-center gap-1 transition-all ${currentPage === item.id ? 'text-primary-500' : 'text-gray-400'}`}
              >
                  <div className={`p-2.5 rounded-2xl transition-all ${currentPage === item.id ? 'bg-primary-500/10 scale-110' : ''}`}><item.icon size={20} /></div>
                  <span className="text-[0.55rem] font-black uppercase tracking-[0.15em]">{item.label}</span>
              </button>
          ))}
      </nav>
    </div>
  );
};

export default App;

