const IncidentDataForm = ({ onComplete, onBack }: { onComplete: (data: any) => void, onBack: () => void }) => {
  const [formData, setFormData] = useState({
    date: '',
    time: '',
    location: '',
    address: '',
    chronology: ''
  });

  const [errors, setErrors] = useState<any>({});

  const validate = () => {
    const newErrors: any = {};
    if (!formData.date) newErrors.date = 'Tanggal wajib diisi';
    if (!formData.time) newErrors.time = 'Waktu wajib diisi';
    if (!formData.address) newErrors.address = 'Lokasi detail wajib diisi';
    if (!formData.chronology) newErrors.chronology = 'Kronologi wajib diisi';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = () => {
    if (validate()) {
      onComplete(formData);
    }
  };

  return (
    <div className="space-y-8 animate-fade-in max-w-lg mx-auto">
        <div className="flex items-center gap-4">
            <button onClick={onBack} className="p-3 bg-white/5 border border-white/10 rounded-2xl text-gray-400 hover:text-white transition-colors"><ChevronLeft size={24}/></button>
            <div>
              <h2 className="text-2xl font-black uppercase tracking-tight text-white leading-none">Data <span className="text-primary-500">Kejadian</span></h2>
              <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest mt-1">Lengkapi informasi insiden</p>
            </div>
        </div>

        <div className="space-y-6">
            <div className="grid grid-cols-2 gap-4">
                <InputField 
                    label="Kapan Terjadi?" 
                    type="date" 
                    icon={Calendar} 
                    value={formData.date} 
                    onChange={(e: any) => setFormData({...formData, date: e.target.value})}
                    error={errors.date}
                />
                <InputField 
                    label="Waktu (WIB)" 
                    type="time" 
                    icon={Clock} 
                    value={formData.time}
                    onChange={(e: any) => setFormData({...formData, time: e.target.value})}
                    error={errors.time}
                />
            </div>

            <div className="space-y-2">
                <label className="text-[0.65rem] font-black uppercase text-gray-400 tracking-[0.2em] ml-1">Lokasi Presisi</label>
                <div className="relative h-48 rounded-[2.5rem] overflow-hidden border border-white/10 bg-white/5 group mb-4">
