                    <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-transparent opacity-60"></div>
                    <div className="absolute inset-0 flex flex-col items-center justify-center p-6 text-center">
                        <div className="w-12 h-12 bg-primary-500 text-white rounded-2xl flex items-center justify-center shadow-[0_0_20px_rgba(16,185,129,0.5)] mb-3 animate-bounce">
                            <MapPin size={24} />
                        </div>
                        <span className="text-[0.7rem] font-black uppercase tracking-widest text-white">Gunakan GPS Lokasi Sekarang</span>
                        <button className="mt-4 px-6 py-2 bg-white/10 hover:bg-white/20 backdrop-blur-md border border-white/20 rounded-full text-[0.6rem] font-black uppercase tracking-widest transition-all">Pilih Manual di Peta</button>
                    </div>
                </div>
                <InputField 
                    placeholder="Alamat Detail / Landmark Terdekat" 
                    icon={Navigation} 
                    value={formData.address}
                    onChange={(e: any) => setFormData({...formData, address: e.target.value})}
                    error={errors.address}
