            </div>

            <div className="bg-primary-500/10 p-6 rounded-[2.5rem] border border-primary-500/20 flex gap-5 items-start">
                <div className="w-10 h-10 bg-primary-500 text-white rounded-xl flex items-center justify-center shrink-0">
                  <Shield size={20} />
                </div>
                <p className="text-[0.65rem] text-primary-400 font-bold leading-relaxed uppercase tracking-wide">
