const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentPage, setPage] = useState('home');
  const [darkMode, setDarkMode] = useState(true);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [isPageTransitioning, setIsPageTransitioning] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsInitialLoading(false), 2500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (darkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [darkMode]);

  const handleNavigate = (pageId: string) => {
    if (pageId === currentPage) return;

    // special case for logout
    if (pageId === 'logout') {
      setIsPageTransitioning(true);
      setTimeout(() => {
        setIsLoggedIn(false);
        setPage('home');
        setIsPageTransitioning(false);
      }, 1000);
      return;
    }

    setIsPageTransitioning(true);
    setTimeout(() => {
      setPage(pageId);
      // Extra small delay to let content mount before removing overlay
      setTimeout(() => setIsPageTransitioning(false), 300);
    }, 800);
  };

  if (isInitialLoading) return (
    <div className="fixed inset-0 bg-[#030303] flex flex-col items-center justify-center z-[100]">
        <LaserBackground />
        <div className="relative">
          <div className="w-24 h-24 bg-primary-500 rounded-[2.5rem] animate-pulse flex items-center justify-center text-white shadow-[0_0_60px_rgba(16,185,129,0.5)] relative z-10">
              <Zap size={48} strokeWidth={3} />
          </div>
          <div className="absolute inset-0 bg-primary-500 blur-[40px] opacity-20 animate-pulse"></div>
        </div>
        <p className="mt-10 font-black uppercase tracking-[0.6em] text-[0.7rem] text-primary-500 animate-fade-in opacity-80">Initialising Neural Link...</p>
    </div>
  );

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-dark-bg relative overflow-hidden">
        {isPageTransitioning && <PageTransitionLoader />}
        <LaserBackground />
        <LoginPortal 
          onLogin={() => setIsLoggedIn(true)} 
          onQuickClaim={() => { setIsLoggedIn(true); setPage('claim'); }} 
        />
      </div>
    );
  }

  const renderContent = () => {
    switch (currentPage) {
      case 'home': return <HomeScreen navigateTo={handleNavigate}/>;
      case 'claim': return <ClaimScreen navigateTo={handleNavigate}/>;
      case 'profile': return <ProfileScreen navigateTo={handleNavigate}/>;
      case 'products': 
        return (
          <div className="p-10 text-center space-y-8 max-w-lg mx-auto relative z-10 pt-20">
              <h2 className="text-4xl font-black uppercase tracking-tight text-white leading-none">Produk <span className="text-primary-500">Retail</span></h2>
              <div className="p-16 bg-white/5 rounded-[3.5rem] border border-dashed border-white/10 backdrop-blur-xl group hover:border-primary-500/50 transition-all">
                  <div className="w-16 h-16 bg-white/5 rounded-2xl flex items-center justify-center mx-auto mb-6 text-gray-500 group-hover:text-primary-500 transition-colors">
                    <Briefcase size={40} />
                  </div>
                  <p className="text-gray-500 font-black uppercase tracking-[0.3em] text-[0.6rem]">Marketplace Integration Pending</p>
              </div>
              <button onClick={() => handleNavigate('home')} className="font-black text-[0.65rem] uppercase tracking-[0.4em] text-primary-500 border-b-2 border-primary-500/20 pb-1">Back to Command Center</button>
          </div>
        );
      case 'console':
        return (
          <div className="p-10 text-center space-y-8 max-w-lg mx-auto relative z-10 pt-20">
              <h2 className="text-4xl font-black uppercase tracking-tight text-white leading-none">Konsol <span className="text-primary-500">Mitra</span></h2>
              <div className="bg-emerald-500/5 border border-emerald-500/10 p-12 rounded-[3.5rem] backdrop-blur-xl">
                  <ScanFace size={48} className="mx-auto mb-6 text-emerald-500 opacity-60" />
                  <p className="text-emerald-500/60 font-black uppercase tracking-[0.3em] text-[0.65rem]">Identitas Partner Terverifikasi</p>
                  <p className="text-xs text-gray-500 mt-4 leading-relaxed font-bold uppercase tracking-widest">Akses Khusus Agen & Surveyor SurePath</p>
              </div>
              <button onClick={() => handleNavigate('home')} className="font-black text-[0.65rem] uppercase tracking-[0.4em] text-primary-500 border-b-2 border-primary-500/20 pb-1">Exit Console</button>
          </div>
        );
      default: return <HomeScreen navigateTo={handleNavigate}/>;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-dark-bg transition-colors duration-500 relative selection:bg-primary-500 selection:text-white">
      {isPageTransitioning && <PageTransitionLoader />}
      <LaserBackground />
