      <header className="fixed top-0 inset-x-0 h-24 bg-white/80 dark:bg-black/40 backdrop-blur-2xl z-40 border-b border-gray-100 dark:border-white/5 px-8 flex items-center justify-between">
          <div className="flex items-center gap-4 cursor-pointer group" onClick={() => handleNavigate('home')}>
              <div className="w-12 h-12 bg-primary-500 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-primary-500/20 group-hover:rotate-12 transition-transform duration-500"><ShieldCheck size={26} strokeWidth={2.5}/></div>
              <span className="text-2xl font-black tracking-tighter uppercase text-white leading-none">Sure<span className="text-primary-500">Path</span></span>
          </div>
          <div className="flex items-center gap-4">
            <button onClick={() => setDarkMode(!darkMode)} className="p-3 bg-white/5 border border-white/5 rounded-2xl hover:bg-white/10 transition-colors text-gray-400">
