// --- HELPERS ---

const formatIDR = (num: number) => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency', currency: 'IDR', minimumFractionDigits: 0
  }).format(num);
};

// --- CUSTOM HOOKS ---

const useMousePosition = () => {
  const [position, setPosition] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setPosition({ x: e.clientX, y: e.clientY });
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return position;
};

// --- ANIMATED BACKGROUND ---

const LaserBackground = ({ mouse }: { mouse?: { x: number, y: number } }) => {
  const parallaxX = mouse ? (mouse.x - window.innerWidth / 2) * 0.02 : 0;
  const parallaxY = mouse ? (mouse.y - window.innerHeight / 2) * 0.02 : 0;

  return (
    <div className="laser-container">
      {/* Background Glow that follows mouse */}
      {mouse && (
        <div 
          className="mouse-glow" 
          style={{ top: mouse.y, left: mouse.x }}
        ></div>
      )}

      {/* Laser Grid Layers with Parallax */}
      <div 
        className="laser-layer" 
        style={{ transform: `translate3d(${parallaxX}px, ${parallaxY}px, 0)` }}
      >
        {[...Array(12)].map((_, i) => (
          <div key={`h-${i}`} className="laser-h" style={{ top: `${i * 8.33}%`, opacity: 0.1 }} />
        ))}
        {[...Array(12)].map((_, i) => (
          <div key={`v-${i}`} className="laser-v" style={{ left: `${i * 8.33}%`, opacity: 0.1 }} />
        ))}
      </div>

      <div 
        className="laser-layer" 
        style={{ transform: `translate3d(${parallaxX * 2}px, ${parallaxY * 2}px, 0)` }}
      >
        {[...Array(5)].map((_, i) => (
          <div 
            key={`dot-${i}`} 
            className="absolute w-1 h-1 bg-primary-500 rounded-full blur-[1px]" 
            style={{ 
              top: `${20 + i * 15}%`, 
              left: `${15 + i * 20}%`,
              boxShadow: '0 0 10px #10b981'
            }} 
          />
        ))}
      </div>

      <div className="absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-black/90"></div>
    </div>
