const ClaimScreen = ({ navigateTo }: { navigateTo: (p: string) => void }) => {
  const [image, setImage] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<ClaimAnalysisData | null>(null);
  const [flowStep, setFlowStep] = useState<'photo' | 'incident' | 'success'>('photo');

  const cameraInputRef = useRef<HTMLInputElement>(null);

  const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      setImage(reader.result as string);
      startAI(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const startAI = async (imgData: string) => {
    setAnalyzing(true);
    setResult(null);
    const res = await analyzeClaimPhoto(imgData);
    if (res.success && res.data) {
      setResult(res.data);
    } else {
      alert("AI Neural engine timeout. Mohon coba lagi dengan foto yang lebih jelas.");
      setImage(null);
    }
    setAnalyzing(false);
  };

  if (flowStep === 'success') {
    return (
        <div className="p-8 text-center space-y-8 animate-pop-in flex flex-col items-center justify-center min-h-[60vh] relative z-10">
