                  <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${vehicle.expansions[opt.id as keyof typeof vehicle.expansions] ? 'border-primary-500 bg-primary-500' : 'border-white/20'}`}>
