const CarInsuranceWizard = ({ navigateTo }: any) => {
  const [step, setStep] = useState(1);
  const [vehicle, setVehicle] = useState({
    brand: '',
    modelCode: '',
    year: 2024,
    price: 0,
    plate: '',
    platePrefix: 'B',
    region: '2' as '1' | '2' | '3',
    insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: { flood: false, earthquake: false, srcc: false, terrorism: false },
    tplLimit: 25000000 // 25 Million default
  });
  const [customer, setCustomer] = useState({ name: '', email: '', phone: '', nik: '' });
  const [paymentMethod, setPaymentMethod] = useState('');

  // Auto detect region from plate
  useEffect(() => {
    const region = getRegionFromPlate(vehicle.platePrefix);
    setVehicle(v => ({ ...v, region }));
  }, [vehicle.platePrefix]);

  const brands = Array.from(new Set(CAR_DATABASE.map(c => c.brand)));
  const models = CAR_DATABASE.filter(c => c.brand === vehicle.brand);

  const calculatePremi = () => {
    const baseRate = getOJKRate(vehicle.price, vehicle.region, vehicle.insuranceType);
    const sumInsured = vehicle.price * 1000000;
    const basePremium = sumInsured * (baseRate / 100);

    let expansionCost = 0;
    if (vehicle.expansions.flood) expansionCost += sumInsured * (EXPANSION_RATES.FLOOD / 100);
    if (vehicle.expansions.earthquake) expansionCost += sumInsured * (EXPANSION_RATES.EARTHQUAKE / 100);

    // Fix: Updated to handle object structure of SRCC and Terrorism in constants.ts
    if (vehicle.expansions.srcc) {
      const r = vehicle.insuranceType === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
      expansionCost += sumInsured * (r / 100);
    }
    if (vehicle.expansions.terrorism) {
      const r = vehicle.insuranceType === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
      expansionCost += sumInsured * (r / 100);
    }

    const tplCost = vehicle.tplLimit * (EXPANSION_RATES.TPL_RATE / 100) * 0.1; // Simple TPL factor

    const adminFee = 50000;
    const total = basePremium + expansionCost + tplCost + adminFee + STAMP_DUTY;

    return { basePremium, expansionCost, tplCost, adminFee, total };
  };

  const premiums = calculatePremi();

  const handlePrint = () => {
    window.print();
  };

