import { GoogleGenAI } from "@google/genai";

export interface ClaimPart {
  namaPart: string;
  kondisi: string;
  tindakan: 'Perbaiki' | 'Ganti';
  estimasiBiaya: number;
}

export interface ClaimAnalysisData {
  severity: 'Ringan' | 'Sedang' | 'Berat' | 'Total Loss';
  totalEstimasi: number;
  rincianPart: ClaimPart[];
  aiInsight: string;
  rekomendasiBengkel: string;
}

export const analyzeClaimPhoto = async (base64Image: string): Promise<{ success: boolean; data?: ClaimAnalysisData; error?: string }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Using gemini-3-flash-preview for fast and accurate visual analysis
  const modelId = 'gemini-3-flash-preview';

  const prompt = `Anda adalah "Surepath Neural AI", sistem pakar asuransi tercanggih. 
  Analisa foto kerusakan kendaraan berikut untuk keperluan klaim asuransi. 
  Berikan hasil analisa yang sangat detail dalam Bahasa Indonesia dengan format JSON murni:
  {
    "severity": "Ringan" | "Sedang" | "Berat" | "Total Loss",
    "totalEstimasi": number (total akumulasi estimasi biaya dalam Rupiah, angka saja),
    "rincianPart": [
      {
        "namaPart": "nama komponen spesifik yang terdeteksi rusak (misal: Bumper Depan Kanan)",
        "kondisi": "penjelasan visual tingkat kerusakan",
        "tindakan": "Perbaiki" | "Ganti",
        "estimasiBiaya": number (estimasi biaya per komponen)
      }
    ],
    "aiInsight": "penjelasan mendalam tentang dampak benturan dan apa yang harus diperhatikan pemilik kendaraan",
    "rekomendasiBengkel": "Saran tipe bengkel (Bengkel Resmi/Authorized atau Bengkel Umum Rekanan)"
  }

  Pastikan semua teks dalam Bahasa Indonesia yang profesional.`;

  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { 
        parts: [
          { text: prompt }, 
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }
        ] 
      },
      config: { 
        responseMimeType: "application/json",
        temperature: 0.2 // Keeping it focused for technical estimation
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return { success: true, data: JSON.parse(text) };
  } catch (error) {
    console.error("Neural AI Analysis Error:", error);
    return { success: false, error: "Gagal menjalankan analisa neural. Pastikan foto jelas dan coba lagi." };
  }
};

