import { GoogleGenAI } from "@google/genai";

export interface ClaimPart {
  namaPart: string;
  kondisi: string;
  tindakan: 'Perbaiki' | 'Ganti';
  estimasiBiaya: number;
}

export interface ClaimAnalysisData {
  severity: 'Ringan' | 'Sedang' | 'Berat' | 'Total Loss';
  totalEstimasi: number;
  rincianPart: ClaimPart[];
  aiInsight: string;
  rekomendasiBengkel: string;
}

// Added VehicleAnalysisData interface for vehicle verification usage in App1.tsx
export interface VehicleAnalysisData {
  overallScore: number;
  insights: string;
}

export const analyzeClaimPhoto = async (base64Image: string): Promise<{ success: boolean; data?: ClaimAnalysisData; error?: string }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Using gemini-3-flash-preview for fast and accurate visual analysis
  const modelId = 'gemini-3-flash-preview';

  const prompt = `Anda adalah "Surepath Neural AI", sistem pakar asuransi tercanggih. 
  Analisa foto kerusakan kendaraan berikut untuk keperluan klaim asuransi. 
  Berikan hasil analisa yang sangat detail dalam Bahasa Indonesia dengan format JSON murni:
  {
    "severity": "Ringan" | "Sedang" | "Berat" | "Total Loss",
    "totalEstimasi": number (total akumulasi estimasi biaya dalam Rupiah, angka saja),
    "rincianPart": [
      {
        "namaPart": "nama komponen spesifik yang terdeteksi rusak (misal: Bumper Depan Kanan)",
        "kondisi": "penjelasan visual tingkat kerusakan",
        "tindakan": "Perbaiki" | "Ganti",
        "estimasiBiaya": number (estimasi biaya per komponen)
      }
    ],
    "aiInsight": "penjelasan mendalam tentang dampak benturan dan apa yang harus diperhatikan pemilik kendaraan",
    "rekomendasiBengkel": "Saran tipe bengkel (Bengkel Resmi/Authorized atau Bengkel Umum Rekanan)"
  }

  Pastikan semua teks dalam Bahasa Indonesia yang profesional.`;

  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { 
        parts: [
          { text: prompt }, 
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }
        ] 
      },
      config: { 
        responseMimeType: "application/json",
        temperature: 0.2 // Keeping it focused for technical estimation
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return { success: true, data: JSON.parse(text) };
  } catch (error) {
    console.error("Neural AI Analysis Error:", error);
    return { success: false, error: "Gagal menjalankan analisa neural. Pastikan foto jelas dan coba lagi." };
  }
};

// Fixed missing exported member analyzeVehiclePhoto for App1.tsx
export const analyzeVehiclePhoto = async (base64Images: string[], labels: string[]): Promise<{ success: boolean; data?: VehicleAnalysisData; error?: string }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelId = 'gemini-3-flash-preview';

  const prompt = `Anda adalah "Surepath Neural AI", sistem verifikasi dokumen dan kendaraan otomatis.
  Analisa rangkaian foto berikut (KTP, STNK, dan foto eksterior/interior mobil) untuk memverifikasi keaslian dan kondisi kendaraan untuk pendaftaran asuransi.

  Daftar foto yang diberikan sesuai urutan: ${labels.join(', ')}.

  Berikan skor verifikasi keseluruhan (0-100) dan penjelasan singkat mengenai validitas dokumen dan kecocokan fisik kendaraan dalam format JSON murni:
  {
    "overallScore": number,
    "insights": "string penjelasan dalam Bahasa Indonesia yang menjelaskan mengapa skor tersebut diberikan"
  }

  Pastikan JSON valid dan Bahasa Indonesia profesional.`;

  try {
    const parts: any[] = [{ text: prompt }];
    base64Images.forEach((base64) => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({ inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } });
    });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts },
      config: { 
        responseMimeType: "application/json",
        temperature: 0.1 // Low temperature for high precision verification
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return { success: true, data: JSON.parse(text) };
  } catch (error) {
    console.error("Vehicle verification Error:", error);
    return { success: false, error: "Gagal menjalankan verifikasi neural. Pastikan semua foto dokumen dan kendaraan jelas." };
  }
};

import { GoogleGenAI } from "@google/genai";

export interface ClaimPart {
  namaPart: string;
  kondisi: string;
  tindakan: 'Perbaiki' | 'Ganti';
  estimasiBiaya: number;
}

export interface ClaimAnalysisData {
  severity: 'Ringan' | 'Sedang' | 'Berat' | 'Total Loss';
  totalEstimasi: number;
  rincianPart: ClaimPart[];
  aiInsight: string;
  rekomendasiBengkel: string;
}

export interface VehicleAnalysisData {
  overallScore: number;
  insights: string;
}

export const analyzeClaimPhoto = async (base64Image: string): Promise<{ success: boolean; data?: ClaimAnalysisData; error?: string }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelId = 'gemini-3-flash-preview';

  const prompt = `Anda adalah "Surepath Neural AI", sistem pakar asuransi tercanggih untuk audit klaim kendaraan. 
  Tugas Anda: Analisa foto kerusakan kendaraan ini dengan presisi tinggi.

  Ketentuan Analisa:
  1. Identifikasi semua komponen/part yang terlihat rusak.
  2. Berikan estimasi biaya perbaikan (jika penyok/gores) atau penggantian (jika pecah/hancur) sesuai harga pasar bengkel resmi di Indonesia.
  3. Klasifikasikan tingkat keparahan.
  4. Berikan insight teknis tentang potensi kerusakan tersembunyi berdasarkan titik benturan.

  WAJIB berikan hasil dalam format JSON murni Bahasa Indonesia:
  {
    "severity": "Ringan" | "Sedang" | "Berat" | "Total Loss",
    "totalEstimasi": number (total akumulasi biaya dlm Rupiah),
    "rincianPart": [
      {
        "namaPart": "string",
        "kondisi": "penjelasan detail kerusakan visual",
        "tindakan": "Perbaiki" | "Ganti",
        "estimasiBiaya": number
      }
    ],
    "aiInsight": "analisa mendalam tentang dampak mekanis benturan ini",
    "rekomendasiBengkel": "Tipe bengkel yang disarankan (Umum/Authorized)"
  }

  Gunakan Bahasa Indonesia profesional. Jangan sertakan teks lain selain JSON.`;

  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { 
        parts: [
          { text: prompt }, 
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }
        ] 
      },
      config: { 
        responseMimeType: "application/json",
        temperature: 0.1 // Low temperature untuk konsistensi estimasi teknis
      }
    });

    const text = response.text;
    if (!text) throw new Error("Gagal menerima respon dari Neural AI");

    return { success: true, data: JSON.parse(text) };
  } catch (error) {
    console.error("Neural AI Claim Error:", error);
    return { success: false, error: "Sistem Neural AI gagal melakukan analisa. Pastikan foto komponen terlihat jelas." };
  }
};

