// --- CLAIM AI SCREEN ---
const ClaimAIScreen = ({ onBack }: { onBack: () => void }) => {
  const [image, setImage] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [result, setResult] = useState<ClaimAnalysisData | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setImage(base64);
      startAnalysis(base64);
    };
    reader.readAsDataURL(file);
  };

  const startAnalysis = async (base64: string) => {
    setIsAnalyzing(true);
    setResult(null);
    const res = await analyzeClaimPhoto(base64);
    if (res.success && res.data) {
      setResult(res.data);
    } else {
      alert(res.error || "Gagal melakukan analisa. Silakan coba lagi.");
      setImage(null);
    }
    setIsAnalyzing(false);
  };

  return (
    <div className="p-6 max-w-lg mx-auto pb-32 space-y-8 animate-fade-in relative z-10">
      <div className="flex items-center gap-4">
        <button onClick={onBack} className="p-3 bg-white/5 border border-white/10 rounded-2xl text-gray-400 hover:text-white transition-colors"><ChevronLeft size={24}/></button>
        <div>
          <h2 className="text-2xl font-black text-white uppercase leading-none">Surepath <span className="text-primary-500">Neural AI</span></h2>
          <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest mt-1">Sistem Deteksi Klaim & Estimasi Biaya</p>
        </div>
      </div>

      {!image ? (
        <div 
          onClick={() => fileInputRef.current?.click()}
          className="aspect-square bg-white/5 border-2 border-dashed border-white/10 rounded-[3rem] flex flex-col items-center justify-center gap-6 cursor-pointer hover:border-primary-500/50 transition-all group backdrop-blur-xl"
        >
          <div className="w-24 h-24 bg-primary-500/10 rounded-3xl flex items-center justify-center text-primary-500 group-hover:scale-110 transition-transform">
            <Camera size={48}/>
          </div>
          <div className="text-center px-8">
            <p className="font-black text-white uppercase text-base mb-2">Unggah Foto Kerusakan</p>
            <p className="text-[0.6rem] text-gray-500 uppercase tracking-widest leading-loose">Ambil foto bagian mobil yang rusak. Neural AI kami akan mengaudit komponen secara otomatis.</p>
          </div>
          <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
        </div>
      ) : (
        <div className="space-y-6 animate-fade-in">
          <div className="relative aspect-video rounded-[3rem] overflow-hidden border-4 border-white/5 bg-black/40 shadow-2xl group">
            <img src={image} className="w-full h-full object-cover" alt="claim-source" />
            {isAnalyzing && (
              <div className="absolute inset-0 bg-black/80 backdrop-blur-md flex flex-col items-center justify-center">
                <div className="scanning-line absolute top-0 w-full z-20"></div>
                <Loader2 className="animate-spin text-primary-500 mb-4" size={56} strokeWidth={3}/>
                <p className="font-black text-white uppercase tracking-[0.4em] text-xs animate-pulse">Neural Analyzing...</p>
              </div>
            )}
            {!isAnalyzing && <button onClick={() => setImage(null)} className="absolute top-6 right-6 p-3 bg-black/60 rounded-2xl text-white hover:bg-black transition-colors"><X size={24}/></button>}
          </div>

          {result && (
            <div className="space-y-6 animate-fade-in">
              <div className="grid grid-cols-2 gap-4">
                <div className="p-8 bg-white/5 border border-white/10 rounded-[2.5rem] backdrop-blur-xl">
                  <p className="text-[0.6rem] font-black text-gray-500 uppercase mb-2 tracking-widest">Keparahan</p>
                  <p className={`text-2xl font-black uppercase ${result.severity === 'Total Loss' ? 'text-red-500' : 'text-white'}`}>{result.severity}</p>
                </div>
                <div className="p-8 bg-primary-500 rounded-[2.5rem] text-white shadow-[0_20px_50px_rgba(16,185,129,0.3)]">
                  <p className="text-[0.6rem] font-black opacity-70 uppercase mb-2 tracking-widest">Total Estimasi</p>
                  <p className="text-2xl font-black">{formatIDR(result.totalEstimasi)}</p>
                </div>
              </div>

              <div className="bg-white/5 border border-white/10 p-8 rounded-[3rem] space-y-6 backdrop-blur-xl">
                <div className="flex justify-between items-center">
                  <h3 className="text-xs font-black uppercase text-primary-500 tracking-[0.2em] flex items-center gap-2">
                    <Wrench size={16}/> Audit Komponen Visual
                  </h3>
                  <span className="text-[0.6rem] font-black text-gray-500 uppercase">{result.rincianPart.length} Part</span>
                </div>
                <div className="space-y-3">
                  {result.rincianPart.map((p, i) => (
                    <div key={i} className="flex justify-between items-center p-5 bg-white/5 rounded-2xl border border-white/5 group hover:border-primary-500/30 transition-all">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
