                      </div>
                      <div className="text-right ml-4">
                        <p className="text-sm font-black text-primary-400 mb-1">{formatIDR(p.estimasiBiaya)}</p>
                        <span className={`text-[0.55rem] font-black px-3 py-1 rounded-lg uppercase tracking-widest ${p.tindakan === 'Ganti' ? 'bg-red-500/20 text-red-400' : 'bg-green-500/20 text-green-400'}`}>{p.tindakan}</span>
                      </div>
