                  ))}
                </div>
              </div>

              <div className="p-8 bg-blue-500/10 border border-blue-500/20 rounded-[3rem] flex gap-5 backdrop-blur-xl">
                <Sparkles className="text-blue-400 shrink-0" size={28}/>
                <div className="space-y-2">
                   <p className="text-[0.6rem] font-black text-blue-400 uppercase tracking-[0.3em]">Neural System Insight</p>
                   <p className="text-xs text-gray-300 leading-loose font-medium italic">"{result.aiInsight}"</p>
                   <div className="pt-2 flex items-center gap-2">
                      <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                      <p className="text-[0.65rem] font-black text-white uppercase">Saran: {result.rekomendasiBengkel}</p>
                   </div>
                </div>
              </div>

              <button onClick={() => alert("Klaim diteruskan ke sistem verifikasi akhir. Nomor tiket: CLM-N-"+Date.now())} className="w-full py-7 bg-primary-500 text-white rounded-[2.5rem] font-black uppercase text-sm shadow-[0_20px_60px_rgba(16,185,129,0.3)] active:scale-95 transition-all">Terbitkan Laporan Klaim Resmi</button>
            </div>
          )}
