// --- CAR INSURANCE WIZARD (Compact) ---
const CarInsuranceWizard = ({ navigateTo }: any) => {
  const [step, setStep] = useState(1);
  const [vehicle, setVehicle] = useState({
    brand: '', modelCode: '', year: 2024, price: 0, plate: '', platePrefix: 'B', region: '2' as '1' | '2' | '3',
    insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: { flood: false, earthquake: false, srcc: false, terrorism: false },
    tplLimit: 25000000
  });
  const [customer, setCustomer] = useState({ name: '', email: '', phone: '', nik: '' });

  useEffect(() => {
    const region = getRegionFromPlate(vehicle.platePrefix);
    setVehicle(v => ({ ...v, region }));
  }, [vehicle.platePrefix]);

  const calculatePremi = () => {
    const baseRate = getOJKRate(vehicle.price, vehicle.region, vehicle.insuranceType);
    const sumInsured = vehicle.price * 1000000;
    const basePremium = sumInsured * (baseRate / 100);
    let expansionCost = 0;
    if (vehicle.expansions.flood) expansionCost += sumInsured * (EXPANSION_RATES.FLOOD / 100);
    if (vehicle.expansions.earthquake) expansionCost += sumInsured * (EXPANSION_RATES.EARTHQUAKE / 100);
    const tplCost = vehicle.tplLimit * (EXPANSION_RATES.TPL_RATE / 100) * 0.1;
    const total = basePremium + expansionCost + tplCost + 50000 + STAMP_DUTY;
    return { total };
  };

  const premiums = calculatePremi();

  return (
    <div className="max-w-2xl mx-auto p-6 pb-32 animate-fade-in relative z-10">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={() => step > 1 ? setStep(step - 1) : navigateTo('products')} className="p-3 bg-white/5 border border-white/10 rounded-2xl text-gray-400 hover:text-white transition-colors"><ChevronLeft size={24} /></button>
        <div className="flex-1">
          <h2 className="text-2xl font-black uppercase text-white">Beli <span className="text-primary-500">Asuransi Mobil</span></h2>
          <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest mt-1">Langkah {step} dari 4</p>
        </div>
      </div>

      {step === 1 && (
        <div className="space-y-6 animate-fade-in">
          <div className="bg-white/5 p-8 rounded-[2.5rem] border border-white/10 space-y-6 backdrop-blur-xl">
             <InputField label="Merk Kendaraan" placeholder="Toyota, Honda, etc" icon={Car} value={vehicle.brand} onChange={(e:any) => setVehicle({...vehicle, brand: e.target.value})} />
             <InputField label="Plat Nomor" placeholder="B 1234 ABC" value={vehicle.plate} onChange={(e:any) => setVehicle({...vehicle, plate: e.target.value.toUpperCase()})} />
          </div>
          <button onClick={() => setStep(2)} className="w-full py-6 bg-primary-500 text-white rounded-[2rem] font-black uppercase tracking-[0.2em] text-[0.75rem] shadow-2xl">Lanjutkan</button>
        </div>
      )}

      {step === 2 && (
        <div className="space-y-6 animate-fade-in">
           <div className="grid grid-cols-2 gap-4">
              {[InsuranceType.COMPREHENSIVE, InsuranceType.TLO].map(t => (
                <button key={t} onClick={() => setVehicle({...vehicle, insuranceType: t})} className={`p-8 rounded-[2.5rem] border-2 transition-all text-left ${vehicle.insuranceType === t ? 'border-primary-500 bg-primary-500/10' : 'border-white/5 bg-white/5'}`}>
                  <p className="font-black text-white uppercase text-sm mb-1">{t}</p>
                  <p className="text-[0.5rem] text-gray-500 font-bold uppercase tracking-widest">Proteksi Penuh</p>
                </button>
              ))}
           </div>
           <button onClick={() => setStep(3)} className="w-full py-6 bg-primary-500 text-white rounded-[2rem] font-black uppercase text-[0.75rem]">Lanjutkan</button>
        </div>
      )}

      {step === 3 && (
        <div className="space-y-6 animate-fade-in">
          <div className="bg-white/5 p-8 rounded-[2.5rem] border border-white/10 space-y-6">
             <InputField label="Nama Lengkap" icon={User} placeholder="Budi Santoso" value={customer.name} onChange={(e:any) => setCustomer({...customer, name: e.target.value})} />
             <InputField label="Email Aktif" icon={Mail} placeholder="budi@email.com" value={customer.email} onChange={(e:any) => setCustomer({...customer, email: e.target.value})} />
          </div>
          <button onClick={() => setStep(4)} className="w-full py-6 bg-primary-500 text-white rounded-[2rem] font-black uppercase text-[0.75rem]">Review Summary</button>
        </div>
      )}

      {step === 4 && (
        <div className="space-y-8 animate-fade-in">
          <div className="bg-white/5 rounded-[3rem] border border-white/10 overflow-hidden shadow-2xl">
             <div className="bg-primary-500 p-10 text-white relative overflow-hidden">
                <Shield className="absolute -right-8 -bottom-8 opacity-10" size={150}/>
                <h3 className="text-[0.6rem] font-black uppercase tracking-[0.4em] mb-4">E-Summary Polis</h3>
                <p className="text-3xl font-black uppercase leading-none mb-1">{vehicle.plate}</p>
                <p className="text-xs font-bold opacity-80 uppercase tracking-widest">Masa Berlaku: 12 Bulan</p>
             </div>
             <div className="p-10 space-y-4">
                <div className="flex justify-between items-center"><span className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest">Tertanggung</span><span className="text-sm font-black text-white uppercase">{customer.name}</span></div>
                <div className="flex justify-between items-center"><span className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest">Total Premi</span><span className="text-2xl font-black text-primary-500 tracking-tighter">{formatIDR(premiums.total)}</span></div>
             </div>
          </div>
          <button onClick={() => setStep(1)} className="w-full py-7 bg-primary-500 text-white rounded-[2.5rem] font-black uppercase tracking-[0.25em] text-[0.8rem] shadow-2xl">Lakukan Pembayaran</button>
        </div>
      )}
    </div>
  );
};

// --- MAIN APP ---
const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentPage, setPage] = useState('home');
  const [darkMode, setDarkMode] = useState(true);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [mouse, setMouse] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => setMouse({ x: e.clientX, y: e.clientY });
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  const navigateTo = (pageId: string) => {
    if (pageId === currentPage) return;
    setIsTransitioning(true);
    setTimeout(() => {
      setPage(pageId);
      setIsTransitioning(false);
    }, 800);
  };

  const handleLogout = () => {
    setIsTransitioning(true);
    setTimeout(() => {
      setIsLoggedIn(false);
      setPage('home');
      setIsTransitioning(false);
    }, 800);
  };

