                  </p>
                </div>
              </div>
            </div>
          </div>

          <button onClick={() => alert('Diteruskan ke portal pembayaran Surepath Secure Pay')} className="w-full py-8 bg-primary-500 text-white rounded-[2.5rem] font-black uppercase tracking-[0.25em] text-[0.8rem] shadow-[0_20px_60px_rgba(16,185,129,0.3)] active:scale-95 transition-all">Lakukan Pembayaran Aman</button>
