/**
 * ClaimAIScreen component for the AI-powered damage analysis flow
 */
const ClaimAIScreen = ({ onBack }: { onBack: () => void }) => {
  const [image, setImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ClaimAnalysisData | null>(null);

  const handleCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        processAnalysis(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const processAnalysis = async (base64: string) => {
    setLoading(true);
    const res = await analyzeClaimPhoto(base64);
    setLoading(false);
    if (res.success && res.data) {
      setResult(res.data);
    } else {
      alert(res.error || "Gagal menganalisa foto");
    }
  };

  return (
    <div className="p-6 space-y-10 animate-fade-in max-w-lg mx-auto pb-32 relative z-10">
      <div className="flex items-center gap-4 mb-4">
        <button onClick={onBack} className="p-3 bg-white/5 border border-white/10 rounded-2xl text-gray-400 hover:text-white">
          <ChevronLeft size={24} />
        </button>
        <h2 className="text-3xl font-black uppercase text-white">Neural <span className="text-primary-500">Claim</span></h2>
      </div>

      {!result ? (
        <div className="space-y-8">
          <div className="aspect-square bg-white/5 border-2 border-dashed border-white/10 rounded-[3rem] flex flex-col items-center justify-center p-12 text-center group hover:border-primary-500/50 transition-all relative overflow-hidden">
            {image ? (
              <img src={image} className="absolute inset-0 w-full h-full object-cover opacity-50" />
            ) : (
              <>
                <div className="w-20 h-20 bg-primary-500/10 rounded-3xl flex items-center justify-center text-primary-500 mb-6 group-hover:scale-110 transition-transform">
                  <Camera size={40} />
                </div>
                <p className="font-black text-white uppercase tracking-tighter text-xl mb-2">Unggah Foto Kerusakan</p>
                <p className="text-xs text-gray-500 font-bold uppercase tracking-widest leading-relaxed">AI akan mendeteksi komponen & estimasi biaya perbaikan secara instan</p>
              </>
            )}
            <input type="file" accept="image/*" onChange={handleCapture} className="absolute inset-0 opacity-0 cursor-pointer" />
