          {loading && (
            <div className="flex flex-col items-center gap-4 py-8">
              <Loader2 className="animate-spin text-primary-500" size={48} />
              <p className="text-[0.6rem] font-black text-primary-500 uppercase tracking-[0.5em] animate-pulse">Analyzing Neural Patterns...</p>
            </div>
          )}
        </div>
      ) : (
        <div className="space-y-6 animate-fade-in">
          <div className="bg-primary-500 p-8 rounded-[3rem] text-white">
            <p className="text-[0.5rem] font-black uppercase tracking-[0.4em] opacity-80 mb-2">Severity Level</p>
            <h3 className="text-4xl font-black uppercase tracking-tighter">{result.severity}</h3>
            <div className="mt-6 pt-6 border-t border-white/20 flex justify-between items-end">
              <div>
                <p className="text-[0.5rem] font-black uppercase tracking-[0.4em] opacity-80 mb-1">Total Estimation</p>
