              </div>
              <ShieldCheck size={40} className="opacity-40" />
            </div>
          </div>

          <div className="bg-white/5 border border-white/10 rounded-[3rem] p-8 space-y-6">
            <h4 className="text-[0.65rem] font-black text-gray-500 uppercase tracking-[0.3em]">Rincian Komponen</h4>
