// --- CAR INSURANCE WIZARD ---
const CarInsuranceWizard = ({ navigateTo }: any) => {
  const [step, setStep] = useState(1);
  const [isOjkModalOpen, setOjkModalOpen] = useState(false);
  const [vehicle, setVehicle] = useState({
    brand: '',
    modelCode: '',
    year: 2024,
    price: 0,
    plate: '',
    platePrefix: 'B',
    region: '2' as '1' | '2' | '3',
    insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: { flood: false, earthquake: false, srcc: false, terrorism: false },
    tplLimit: 25000000,
    selectedProvider: null as any
  });
  const [customer, setCustomer] = useState({ name: '', email: '', phone: '', nik: '' });

  useEffect(() => {
    const region = getRegionFromPlate(vehicle.platePrefix);
    setVehicle(v => ({ ...v, region }));
  }, [vehicle.platePrefix]);

  const brands = Array.from(new Set(CAR_DATABASE.map(c => c.brand)));
  const models = CAR_DATABASE.filter(c => c.brand === vehicle.brand);

  const calculatePremi = () => {
    const baseRate = getOJKRate(vehicle.price, vehicle.region, vehicle.insuranceType);
    const sumInsured = vehicle.price * 1000000;
    const basePremium = sumInsured * (baseRate / 100);

    let floodCost = vehicle.expansions.flood ? sumInsured * (EXPANSION_RATES.FLOOD / 100) : 0;
    let earthquakeCost = vehicle.expansions.earthquake ? sumInsured * (EXPANSION_RATES.EARTHQUAKE / 100) : 0;
    let srccRate = vehicle.insuranceType === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    let srccCost = vehicle.expansions.srcc ? sumInsured * (srccRate / 100) : 0;
    let terrorismRate = vehicle.insuranceType === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    let terrorismCost = vehicle.expansions.terrorism ? sumInsured * (terrorismRate / 100) : 0;

    const tplCost = (vehicle.tplLimit / 1000000) * 10000; // Simplified logic: 10k per 1M limit

    const adminFee = vehicle.selectedProvider?.adminFee || 50000;
    const total = basePremium + floodCost + earthquakeCost + srccCost + terrorismCost + tplCost + adminFee + STAMP_DUTY;

    return { basePremium, floodCost, earthquakeCost, srccCost, terrorismCost, tplCost, adminFee, total };
  };

  const premiums = calculatePremi();

  return (
    <div className="max-w-2xl mx-auto p-6 pb-32 animate-fade-in relative z-10">
      {/* Header Wizard */}
      <div className="flex items-center gap-4 mb-8">
        <button onClick={() => step > 1 ? setStep(step - 1) : navigateTo('products')} className="p-3 bg-white/5 border border-white/10 rounded-2xl text-gray-400 hover:text-white transition-colors">
          <ChevronLeft size={24} />
        </button>
        <div className="flex-1">
          <h2 className="text-2xl font-black uppercase text-white leading-none">Smart <span className="text-primary-500">Auto Protection</span></h2>
          <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest mt-1">Langkah {step} dari 5</p>
        </div>
      </div>

      {/* Step 1: Vehicle Details */}
      {step === 1 && (
        <div className="space-y-6 animate-fade-in">
          <div className="bg-white/5 p-8 rounded-[2.5rem] border border-white/10 space-y-6 backdrop-blur-xl">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-[0.6rem] font-black uppercase text-gray-500 tracking-widest ml-1">Merk</label>
                <select className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-4 outline-none text-white font-bold" value={vehicle.brand} onChange={(e) => setVehicle({...vehicle, brand: e.target.value})}>
                  <option value="" disabled className="bg-[#111]">Pilih Merk</option>
                  {brands.map(b => <option key={b} value={b} className="bg-[#111]">{b}</option>)}
                </select>
              </div>
              <div className="space-y-1.5">
                <label className="text-[0.6rem] font-black uppercase text-gray-500 tracking-widest ml-1">Model</label>
                <select disabled={!vehicle.brand} className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-4 outline-none text-white font-bold disabled:opacity-30" value={vehicle.modelCode} onChange={(e) => {
                    const m = models.find(mod => mod.code === e.target.value);
                    setVehicle({...vehicle, modelCode: e.target.value, price: m?.yearPrices[vehicle.year] || 0});
                  }}>
                  <option value="" disabled className="bg-[#111]">Pilih Model</option>
                  {models.map(m => <option key={m.code} value={m.code} className="bg-[#111]">{m.modelName}</option>)}
                </select>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-[0.6rem] font-black uppercase text-gray-500 tracking-widest ml-1">Tahun</label>
                <select className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-4 outline-none text-white font-bold" value={vehicle.year} onChange={(e) => setVehicle({...vehicle, year: parseInt(e.target.value)})}>
                  {[2025, 2024, 2023, 2022, 2021].map(y => <option key={y} value={y} className="bg-[#111]">{y}</option>)}
                </select>
              </div>
