  2. Berikan estimasi biaya perbaikan (jika penyok/gores) atau penggantian (jika pecah/hancur) sesuai harga pasar bengkel resmi di Indonesia (IDR).
  3. Klasifikasikan tingkat keparahan (Ringan/Sedang/Berat/Total Loss).
  4. Berikan insight teknis tentang potensi kerusakan tersembunyi berdasarkan titik benturan.

  WAJIB berikan hasil dalam format JSON murni Bahasa Indonesia:
  {
    "severity": "string",
    "totalEstimasi": number,
    "rincianPart": [
      {
        "namaPart": "string",
        "kondisi": "string",
        "tindakan": "Perbaiki" | "Ganti",
        "estimasiBiaya": number
      }
    ],
    "aiInsight": "string",
    "rekomendasiBengkel": "string"
  }

  Gunakan Bahasa Indonesia profesional. Jangan sertakan teks lain selain JSON.`;

  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { 
        parts: [
          { text: prompt }, 
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }
        ] 
      },
      config: { 
        responseMimeType: "application/json",
        thinkingConfig: { thinkingBudget: 32768 } // Enable thinking mode with max budget
      }
    });

    const text = response.text;
    if (!text) throw new Error("Gagal menerima respon dari Neural AI");

    return { success: true, data: JSON.parse(text) };
  } catch (error) {
    console.error("Neural AI Claim Error:", error);
    return { success: false, error: "Sistem Neural AI gagal melakukan analisa. Pastikan foto komponen terlihat jelas." };
  }
};

export const analyzeVehiclePhoto = async (base64Images: string[], labels: string[]): Promise<{ success: boolean; data?: VehicleAnalysisData; error?: string }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelId = 'gemini-3-pro-preview';

  const prompt = `Anda adalah "Surepath Neural AI", sistem verifikasi dokumen dan kendaraan otomatis.
  Analisa rangkaian foto berikut (KTP, STNK, dan foto eksterior/interior mobil) untuk memverifikasi keaslian dan kondisi kendaraan untuk pendaftaran asuransi.

  Daftar foto yang diberikan sesuai urutan: ${labels.join(', ')}.

  Berikan skor verifikasi keseluruhan (0-100) dan penjelasan singkat mengenai validitas dokumen dan kecocokan fisik kendaraan dalam format JSON murni:
  {
    "overallScore": number,
    "insights": "string"
  }

  Pastikan JSON valid dan Bahasa Indonesia profesional.`;

  try {
    const parts: any[] = [{ text: prompt }];
    base64Images.forEach((base64) => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({ inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } });
    });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts },
      config: { 
        responseMimeType: "application/json",
        thinkingConfig: { thinkingBudget: 32768 }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return { success: true, data: JSON.parse(text) };
  } catch (error) {
    console.error("Vehicle verification Error:", error);
    return { success: false, error: "Gagal menjalankan verifikasi neural. Pastikan semua foto dokumen dan kendaraan jelas." };
  }
};

