                  {models.map(m => <option key={m.code} value={m.code}>{m.modelName}</option>)}
                </select>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-[0.6rem] font-black uppercase text-gray-500 tracking-widest ml-1">Tahun</label>
                <select className="w-full bg-gray-50 dark:bg-[#111] border border-gray-200 dark:border-white/10 rounded-2xl py-4 px-4 outline-none text-gray-900 dark:text-white font-bold transition-all focus:border-primary-500" value={vehicle.year} onChange={(e) => setVehicle({...vehicle, year: parseInt(e.target.value)})}>
