               <Shield className="absolute -right-8 -bottom-8 opacity-10" size={180}/>
               <div className="flex justify-between items-start mb-6">
                 <div>
                    <h3 className="text-[0.65rem] font-black uppercase tracking-[0.4em] opacity-80 mb-2">E-Summary Quote</h3>
