// --- MAIN APP COMPONENT ---

const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentPage, setPage] = useState('home');
  const [darkMode, setDarkMode] = useState(true);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [mouse, setMouse] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => setMouse({ x: e.clientX, y: e.clientY });
    window.addEventListener('mousemove', handleMouseMove);

    // Manage class on root
    if (darkMode) {
      document.documentElement.classList.add('dark');
      document.documentElement.classList.remove('light');
    } else {
      document.documentElement.classList.remove('dark');
      document.documentElement.classList.add('light');
    }

    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [darkMode]);

  const navigateTo = (pageId: string) => {
    if (pageId === currentPage) return;
    setIsTransitioning(true);
    setTimeout(() => {
      setPage(pageId);
      setIsTransitioning(false);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }, 800);
  };

  const handleLogout = () => {
    setIsTransitioning(true);
    setTimeout(() => {
      setIsLoggedIn(false);
      setPage('home');
      setIsTransitioning(false);
    }, 800);
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-white dark:bg-dark-bg transition-colors duration-500 relative overflow-hidden flex items-center justify-center">
        <LaserBackground mouse={mouse} />
        {isTransitioning && <PageTransitionLoader />}
        <div className="min-h-screen flex flex-col items-center justify-center p-6 space-y-12 animate-fade-in relative z-10 w-full max-w-lg">
          <div className="text-center space-y-4">
            <div className="w-24 h-24 bg-primary-500/10 border border-primary-500/20 rounded-[3rem] flex items-center justify-center text-primary-500 shadow-neural mx-auto mb-8 relative group overflow-hidden">
              <ShieldCheck size={56} strokeWidth={2} className="relative z-10" />
              <div className="absolute inset-0 bg-primary-500/10 animate-pulse"></div>
            </div>
            <h1 className="text-7xl font-black tracking-tighter uppercase text-gray-900 dark:text-white leading-none">Sure<span className="text-primary-500">Path</span></h1>
            <p className="text-gray-500 dark:text-gray-400 text-[0.7rem] font-bold uppercase tracking-[0.8em] opacity-40">Command Center v3.0</p>
          </div>

          <div className="w-full glass-card p-12 rounded-[4rem] relative overflow-hidden group transition-transform duration-200 shadow-2xl border border-gray-100 dark:border-white/10">
            <div className="space-y-6 relative z-10">
              <InputField label="Akses Portal" placeholder="Email atau ID Agen" icon={Mail} />
              <InputField label="Keamanan" type="password" placeholder="Masukkan Password" icon={Lock} />
