// --- CLAIM AI SCREEN ---

const ClaimAIScreen = ({ onBack }: { onBack: () => void }) => {
  const [image, setImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ClaimAnalysisData | null>(null);

  const handleCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        setImage(base64);
        processAnalysis(base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const processAnalysis = async (base64: string) => {
    setLoading(true);
    const res = await analyzeClaimPhoto(base64);
    setLoading(false);
    if (res.success && res.data) {
      setResult(res.data);
    } else {
      alert(res.error || "Gagal menganalisa foto");
      setImage(null);
    }
  };

  return (
    <div className="p-6 space-y-10 animate-fade-in max-w-lg mx-auto pb-32 relative z-10">
      <div className="flex items-center gap-4 mb-4">
        <button onClick={onBack} className="p-3 bg-white dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-2xl text-gray-400 hover:text-gray-900 dark:hover:text-white transition-colors shadow-premium dark:shadow-none">
          <ChevronLeft size={24} />
        </button>
        <div>
          <h2 className="text-3xl font-black uppercase text-gray-900 dark:text-white leading-none">Neural <span className="text-primary-500">Claim</span></h2>
          <p className="text-[0.55rem] font-bold text-gray-500 uppercase tracking-widest mt-1">Audit Kerusakan Pro-AI</p>
