      </div>

      {!result ? (
        <div className="space-y-8">
          <div className="aspect-square bg-white dark:bg-white/5 border-2 border-dashed border-gray-200 dark:border-white/10 rounded-[3rem] flex flex-col items-center justify-center p-12 text-center group hover:border-primary-500/50 transition-all relative overflow-hidden backdrop-blur-xl shadow-premium dark:shadow-none">
            {image ? (
              <img src={image} className="absolute inset-0 w-full h-full object-cover opacity-50" />
