      <nav className="fixed bottom-10 inset-x-10 h-28 bg-white/60 dark:bg-black/60 backdrop-blur-3xl border border-gray-200 dark:border-white/10 z-50 flex items-center justify-around px-12 rounded-[4rem] shadow-premium dark:shadow-[0_50px_100px_rgba(0,0,0,0.9)] max-w-lg mx-auto">
