      ) : (
        <div className="space-y-6 animate-fade-in">
          <div className="bg-primary-500 p-10 rounded-[3rem] text-white shadow-neural">
            <p className="text-[0.5rem] font-black uppercase tracking-[0.4em] opacity-80 mb-2">Audit Keparahan</p>
