const ClaimAIScreen = ({ onBack }: { onBack: () => void }) => {
  const [image, setImage] = useState<string | null>(null);
  const [uploadStatus, setUploadStatus] = useState<'idle' | 'scanning' | 'success' | 'error'>('idle');
  const [result, setResult] = useState<ClaimAnalysisData | null>(null);

  const handleCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        setImage(base64);
        processAnalysis(base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const processAnalysis = async (base64: string) => {
    setUploadStatus('scanning');
    const res = await analyzeClaimPhoto(base64);
    if (res.success && res.data) {
      setUploadStatus('success');
      setResult(res.data);
    } else {
      setUploadStatus('error');
      alert(res.error || "Gagal menganalisa foto");
    }
  };

  return (
    <div className="p-6 space-y-10 animate-fade-in max-w-lg mx-auto pb-32">
      <div className="flex items-center gap-4">
        <button onClick={onBack} className="p-3 bg-white dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-2xl">
          <ChevronLeft size={24} />
        </button>
        <h2 className="text-3xl font-black uppercase leading-none">Neural <span className="text-primary-500">Claim</span></h2>
      </div>

      {!result ? (
        <div className="space-y-8">
          <div className={`aspect-square relative overflow-hidden rounded-[3rem] border-2 border-dashed transition-all ${
            uploadStatus === 'scanning' ? 'border-blue-500' : 
            uploadStatus === 'success' ? 'border-primary-500' : 
            uploadStatus === 'error' ? 'border-red-500' : 'border-gray-200'
          }`}>
            {image ? (
              <>
                <img src={image} className="absolute inset-0 w-full h-full object-cover" />
                {uploadStatus === 'scanning' && <div className="absolute inset-0 scanning-line"></div>}
                {uploadStatus === 'success' && (
                  <div className="absolute top-4 right-4 bg-primary-500 text-white p-2 rounded-full shadow-lg animate-pop-in">
                    <CheckCircle2 size={32} />
                  </div>
                )}
              </>
            ) : (
              <div className="flex flex-col items-center justify-center h-full p-12 text-center">
                <Camera size={48} className="text-primary-500 mb-4" />
                <p className="font-bold">Unggah Foto Kerusakan</p>
                <p className="text-xs text-gray-500 uppercase mt-2">AI akan mendeteksi estimasi biaya secara otomatis</p>
              </div>
            )}
            <input type="file" accept="image/*" onChange={handleCapture} className="absolute inset-0 opacity-0 cursor-pointer" />
          </div>
          {uploadStatus === 'scanning' && (
            <div className="text-center animate-pulse">
               <p className="text-[0.6rem] font-black text-primary-500 uppercase tracking-[0.5em]">Analyzing Neural Patterns...</p>
            </div>
          )}
        </div>
      ) : (
        <div className="space-y-6 animate-fade-in">
          <div className="bg-primary-500 p-8 rounded-[3rem] text-white">
            <p className="text-[0.5rem] font-black uppercase opacity-80 mb-1">Keparahan: {result.severity}</p>
            <h3 className="text-3xl font-black">{formatIDR(result.totalEstimasi)}</h3>
