              <button onClick={() => setPage('products')} className="p-10 rounded-[3rem] bg-white dark:bg-white/5 border border-gray-100 dark:border-white/10 text-left space-y-4 shadow-premium">
                <Grid size={32} className="text-blue-500"/>
                <p className="font-black uppercase tracking-tighter text-xl leading-none">Beli Polis</p>
              </button>
              <button onClick={() => setPage('claim')} className="p-10 rounded-[3rem] bg-white dark:bg-white/5 border border-gray-100 dark:border-white/10 text-left space-y-4 shadow-premium">
                <Zap size={32} className="text-primary-500"/>
                <p className="font-black uppercase tracking-tighter text-xl leading-none">Klaim AI</p>
              </button>
            </div>
          </div>
        )}

        {currentPage === 'products' && (
          <div className="p-6 max-w-lg mx-auto space-y-8">
            <h2 className="text-3xl font-black uppercase">Command <span className="text-primary-500">Store</span></h2>
            <button onClick={() => setPage('car-flow')} className="w-full p-10 bg-white dark:bg-white/5 border border-gray-100 dark:border-white/10 rounded-[4rem] text-left flex justify-between items-center group shadow-premium">
              <div className="flex items-center gap-6">
                <div className="w-16 h-16 bg-blue-50 dark:bg-blue-500/10 rounded-[1.5rem] flex items-center justify-center text-blue-500"><Car size={32}/></div>
                <div>
                   <p className="text-2xl font-black uppercase tracking-tighter">Asuransi Mobil</p>
                   <p className="text-[0.6rem] text-gray-500 uppercase">Rate Batas Bawah OJK</p>
                </div>
              </div>
              <ChevronRight className="text-gray-300 group-hover:text-primary-500"/>
            </button>
          </div>
        )}

        {currentPage === 'car-flow' && <CarInsuranceWizard navigateTo={setPage} />}
        {currentPage === 'claim' && <ClaimAIScreen onBack={() => setPage('home')} />}
      </main>

      <nav className="fixed bottom-10 inset-x-10 h-24 bg-white/60 dark:bg-black/60 backdrop-blur-3xl border border-gray-200 dark:border-white/10 z-50 flex items-center justify-around px-8 rounded-[3rem] shadow-2xl max-w-lg mx-auto">
        {[
          { id: 'home', icon: Home, label: 'Portal' },
          { id: 'products', icon: Grid, label: 'Store' },
          { id: 'claim', icon: Zap, label: 'Neural' },
          { id: 'profile', icon: User, label: 'Profile' }
        ].map(item => (
          <button key={item.id} onClick={() => setPage(item.id)} className={`flex flex-col items-center gap-1 ${currentPage === item.id ? 'text-primary-500' : 'text-gray-400'}`}>
            <item.icon size={24} />
            <span className="text-[0.5rem] font-black uppercase tracking-widest">{item.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

